window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[24]={"id":"024","numero":24,"titre":"Principales complications de la grossesse","objectifs":[{"id":"24-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la prise en charge d’une hémorragie du premier trimestre","contenu":"<p>Les hémorragies du 1er trimestre concernent <span class=\"kw-chiffre\">25 %</span> des grossesses ; <strong><span class=\"kw-chiffre\">50 %</span> de ces femmes auront une <span class=\"kw-clinique\">évolution</span> défavorable</strong>. Trois diagnostics dominent : <span class=\"kw-etio\">GIU évolutive</span> avec <span class=\"kw-etio\">hématome décidual</span>, <span class=\"kw-etio\">fausse couche spontanée</span>, <span class=\"kw-etio\">GEU</span>.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Dogme.</strong> Toute femme avec hémorragie du 1er trimestre = <span class=\"kw-alerte\">GEU jusqu’à preuve du contraire</span>.\n      </div>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 620 282\" role=\"img\" aria-label=\"Arbre décisionnel devant des métrorragies du premier trimestre, qui sont une grossesse extra-utérine jusqu'à preuve du contraire. Première étape : examen au spéculum pour éliminer une cause cervico-vaginale, dosage des béta-hCG plasmatiques et groupe Rhésus RAI. Deuxième étape : échographie pelvienne par voie endovaginale, qui oriente vers trois diagnostics. Premier : grossesse intra-utérine évolutive si sac intra-utérin conforme avec embryon et activité cardiaque, et béta-hCG qui doublent à 48 heures. Deuxième : grossesse extra-utérine si utérus vide avec béta-hCG supérieurs à 1500, parfois masse latéro-utérine, et béta-hCG en stagnation à 48 heures. Troisième : fausse couche spontanée si œuf clair ou sac aplati ou embryon sans activité cardiaque, et béta-hCG en décroissance à 48 heures.\" style=\"height:auto;display:block;border-radius:8px\">\n          <rect class=\"fb-blue\" x=\"160\" y=\"12\" width=\"300\" height=\"44\" rx=\"6\"/>\n          <text class=\"tx-blue\" x=\"310\" y=\"30\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">Métrorragies du 1ᵉʳ trimestre</text>\n          <text class=\"tx-blue\" x=\"310\" y=\"47\" text-anchor=\"middle\" font-size=\"9.5\">→ GEU jusqu’à preuve du contraire</text>\n\n          <line class=\"ln\" x1=\"310\" y1=\"56\" x2=\"310\" y2=\"72\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"310,74 305,66 315,66\"/>\n\n          <rect class=\"fb-grey\" x=\"140\" y=\"74\" width=\"340\" height=\"34\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"310\" y=\"95\" text-anchor=\"middle\" font-size=\"10\">Spéculum + β-hCG plasmatique + groupe-Rhésus-RAI</text>\n\n          <line class=\"ln\" x1=\"310\" y1=\"108\" x2=\"310\" y2=\"122\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"310,124 305,116 315,116\"/>\n\n          <rect class=\"fb-teal\" x=\"200\" y=\"124\" width=\"220\" height=\"30\" rx=\"6\"/>\n          <text class=\"tx-teal\" x=\"310\" y=\"143\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"600\"><span class=\"kw-imagerie\">Échographie</span> endovaginale</text>\n\n          <line class=\"ln\" x1=\"310\" y1=\"154\" x2=\"310\" y2=\"168\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"110\" y1=\"168\" x2=\"510\" y2=\"168\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"110\" y1=\"168\" x2=\"110\" y2=\"180\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"110,182 105,174 115,174\"/>\n          <line class=\"ln\" x1=\"310\" y1=\"168\" x2=\"310\" y2=\"180\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"310,182 305,174 315,174\"/>\n          <line class=\"ln\" x1=\"510\" y1=\"168\" x2=\"510\" y2=\"180\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"510,182 505,174 515,174\"/>\n\n          <rect class=\"fb-ok\" x=\"15\" y=\"182\" width=\"190\" height=\"86\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"110\" y=\"201\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\">GIU évolutive</text>\n          <text class=\"tx-ok\" x=\"110\" y=\"217\" text-anchor=\"middle\" font-size=\"9\">Sac IU conforme + embryon</text>\n          <text class=\"tx-ok\" x=\"110\" y=\"231\" text-anchor=\"middle\" font-size=\"9\">+ activité cardiaque</text>\n          <text class=\"tx-ok\" x=\"110\" y=\"252\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">β-hCG : doublement /<span class=\"kw-chiffre\">48 h</span></text>\n\n          <rect class=\"fb-red\" x=\"215\" y=\"182\" width=\"190\" height=\"86\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"310\" y=\"201\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\">GEU</text>\n          <text class=\"tx-red\" x=\"310\" y=\"217\" text-anchor=\"middle\" font-size=\"9\">Utérus vide + β-hCG &gt; 1500</text>\n          <text class=\"tx-red\" x=\"310\" y=\"231\" text-anchor=\"middle\" font-size=\"9\">± <span class=\"kw-clinique\">masse</span> latéro-utérine</text>\n          <text class=\"tx-red\" x=\"310\" y=\"252\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">β-hCG : stagnation /<span class=\"kw-chiffre\">48 h</span></text>\n\n          <rect class=\"fb-amber\" x=\"415\" y=\"182\" width=\"190\" height=\"86\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"510\" y=\"201\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\">Fausse couche spontanée</text>\n          <text class=\"tx-amber\" x=\"510\" y=\"217\" text-anchor=\"middle\" font-size=\"9\">Œuf clair / sac aplati</text>\n          <text class=\"tx-amber\" x=\"510\" y=\"231\" text-anchor=\"middle\" font-size=\"9\">ou embryon sans AC</text>\n          <text class=\"tx-amber\" x=\"510\" y=\"252\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">β-hCG : décroissance /<span class=\"kw-chiffre\">48 h</span></text>\n        </svg>\n        <figcaption>La <strong>cinétique des β-hCG à<span class=\"kw-chiffre\"> 48 h</span></strong> oriente mais n’élimine jamais formellement : toute cinétique peut se voir en GEU → contrôle écho à 5-7 j si doute.</figcaption>\n      </figure>\n\n      <h4>Étiologies du 1er trimestre</h4>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Fréquence / particularités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">GIU évolutive</span> + <span class=\"kw-etio\">hématome décidual</span></strong></td><td><span class=\"kw-chiffre\">12 %</span> — saignement bénin, abdomen indolore, écho conforme à l’âge gestationnel + <span class=\"kw-radio\">image liquidienne entre œuf et paroi</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Avortement spontané</span> (<span class=\"kw-etio\">fausse couche</span>)</strong></td><td><span class=\"kw-chiffre\">12 %</span> — métrorragies rouges abondantes avec caillots/débris, douleurs « comme des règles »</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">GEU</span></strong></td><td><span class=\"kw-chiffre\">1 %</span> — sang sépia, douleurs latéralisées, β-hCG &gt; 1500 + vacuité utérine</td></tr>\n          <tr><td><strong>Causes cervico-vaginales</strong></td><td>Au spéculum : <span class=\"kw-clinique\">cancer du col</span>, ectropion, cervicite, polype</td></tr>\n          <tr><td><strong>Rares</strong></td><td>Lyse d’un jumeau (gémellaire), <span class=\"kw-clinique\">grossesse môlaire</span> (hCG &gt; 100 000, <span class=\"kw-radio\">« nid d’abeilles »</span> écho)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>CAT systématique devant métrorragies du 1er trimestre</h4>\n      <ol>\n        <li><strong>Examen au spéculum</strong> — différencier origine cervico-vaginale <span class=\"kw-bio\">vs</span> endo-utérine</li>\n        <li><span class=\"kw-bio\">β-hCG plasmatique</span> en cas de doute sur l’état de <span class=\"kw-ci\">grossesse</span> + <span class=\"kw-bio\">groupe sanguin + Rhésus + RAI</span> systématiques ⭐</li>\n        <li><span class=\"kw-imagerie\">Échographie pelvienne par voie endovaginale</span> + abdominale (recherche hémopéritoine)</li>\n        <li>Si <strong>Rh-</strong> et fœtus Rh+ ou inconnu : <span class=\"kw-ttt\">Ig anti-D</span> dans les <span class=\"kw-chiffre\">72 h</span></li>\n      </ol>\n\n      <h4>Orientation clinique synthétique</h4>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-etio\">GIU évolutive</span></th><th><span class=\"kw-etio\">GEU</span></th><th><span class=\"kw-etio\">Avortement spontané</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Signes sympathiques</strong></td><td>Oui</td><td>Oui</td><td><span class=\"kw-alerte\">Disparition</span> ⭐</td></tr>\n          <tr><td><strong>Douleurs</strong></td><td>Absentes ⭐</td><td>Latéralisées, sourdes</td><td>Médianes, intermittentes</td></tr>\n          <tr><td><strong>Métrorragies</strong></td><td>Faibles</td><td>Peu abondantes, noirâtres (sépia)</td><td>Abondantes, rouges, avec caillots/débris</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">TV</span> col</strong></td><td>Fermé</td><td>Tonique, fermé</td><td>Mou, perméable au doigt</td></tr>\n          <tr><td><strong>Utérus</strong></td><td>Taille = terme</td><td>Plus petit qu’attendu ± <span class=\"kw-clinique\">masse</span> latéro-utérine</td><td>Taille = terme</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-imagerie\">Échographie</span> pelvienne — résultats normaux et interprétation</h4>\n      <ul>\n        <li><strong>Sac ovulaire intra-utérin</strong> (<span class=\"kw-radio\">image liquidienne entourée d’une couronne échogène trophoblastique</span>) : visible dès <span class=\"kw-chiffre\">5 SA</span></li>\n        <li><strong>Embryon + activité cardiaque</strong> : entre <span class=\"kw-chiffre\">5,5 et 6 SA</span></li>\n        <li><strong>Sac intra-utérin conforme</strong> → <span class=\"kw-etio\">GIU évolutive</span></li>\n        <li><strong><span class=\"kw-radio\">Œuf clair, aplati, contour irrégulier, petit</span></strong> → <span class=\"kw-etio\">avortement spontané</span></li>\n        <li><strong><span class=\"kw-radio\">Utérus vide</span></strong> avec β-hCG &gt; 1500 → <span class=\"kw-etio\">GEU</span> jusqu’à preuve du contraire ; <span class=\"kw-radio\">masse hétérogène floconneuse vésiculaire</span> → <span class=\"kw-etio\">môle</span></li>\n        <li><strong>Si doute</strong> : refaire écho <span class=\"kw-chiffre\">5-7 jours</span> après le 1er contrôle</li>\n      </ul>\n\n      <h4>Cinétique des β-hCG à <span class=\"kw-chiffre\">48 h</span></h4>\n      <ul>\n        <li><strong>Doublement</strong> → <span class=\"kw-ci\">grossesse</span> évolutive (GIU le plus souvent, parfois <span class=\"kw-etio\">GEU</span>)</li>\n        <li><strong>Décroissance × 2</strong> → <span class=\"kw-etio\">fausse couche spontanée</span></li>\n        <li><strong>Stagnation ou élévation insuffisante</strong> → <span class=\"kw-etio\">GEU</span> plutôt</li>\n        <li><em>KB :</em> toute cinétique peut se voir en <span class=\"kw-etio\">GEU</span> — la cinétique oriente mais n’élimine jamais formellement</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — GEU · 43 — Hémorragie génitale chez la femme · 23 — <span class=\"kw-ci\">Grossesse</span> normale · 27 — Prévention des risques fœtaux</em></p>","frequence":1},{"id":"24-2","rang":"A","rubrique":"Prise en charge","titre":"Connaître la prise en charge une fausse couche du premier trimestre","contenu":"<p>La <span class=\"kw-def\">fausse couche spontanée précoce (FCP)</span> = expulsion d’une GIU avant <span class=\"kw-chiffre\">14 SA</span>. Fréquence <span class=\"kw-chiffre\">10-15 %</span> des grossesses. Cause principale : <strong>anomalie chromosomique embryonnaire (<span class=\"kw-chiffre\">60 %</span>)</strong>.</p>\n\n      <h4>Terminologie clé</h4>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ci\">Grossesse</span> de localisation indéterminée</strong></td><td>hCG positif mais écho ne visualisant aucune <span class=\"kw-ci\">grossesse</span></td></tr>\n          <tr><td><strong>GIU d’<span class=\"kw-clinique\">évolution</span> incertaine</strong></td><td>Sac gestationnel &lt; <span class=\"kw-chiffre\">25 mm</span> sans embryon, ou embryon avec LCC &lt; <span class=\"kw-chiffre\">7 mm</span> sans activité cardiaque</td></tr>\n          <tr><td><strong><span class=\"kw-ci\">Grossesse</span> arrêtée précoce</strong></td><td>Arrêt &lt; <span class=\"kw-chiffre\">14 SA</span> : stagnation du sac et/ou LCC, disparition de l’AC</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">FCP</span> complète</strong></td><td>Vacuité utérine + absence de symptôme</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">FCP</span> incomplète</strong></td><td>Persistance de matériel intra-utérin à l’écho</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Diagnostic positif</span></h4>\n      <ul>\n        <li><strong>Clinique :</strong> disparition récente des signes sympathiques + métrorragies rouges franches avec caillots/débris + douleurs médianes intermittentes « comme des règles »</li>\n        <li><strong><span class=\"kw-alerte\">TV</span> :</strong> col mou perméable au doigt (ouvert après expulsion), culs-de-sac libres, mobilisation utérine indolore</li>\n        <li><strong>Écho :</strong> sac ovulaire reconnaissable mais anormal — embryon sans AC, ou œuf clair sans embryon, aplati, à contours irréguliers</li>\n      </ul>\n\n      <h4>Stratégies thérapeutiques</h4>\n      <table >\n        <thead><tr><th>Option</th><th>Indications / modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Abstention surveillée</strong></td><td>Expulsion spontanée dans la majorité des cas (avec majoration transitoire d’hémorragie et douleurs)</td></tr>\n          <tr><td><strong>Traitement médical</strong> — <span class=\"kw-ttt\">misoprostol</span> (prostaglandine)</td><td>Si <strong>œuf de petite taille</strong> et <strong>hémorragies peu importantes</strong>. À éviter si <span class=\"kw-etio\">FCP</span> avec fœtus déjà expulsé.</td></tr>\n          <tr><td><strong>Traitement chirurgical</strong></td><td><span class=\"kw-alerte\">Hospitalisation</span> + bilan préop + consultation anesthésie. AG ou AL : <strong>dilatation du col + aspiration à la canule</strong> + <strong>examen anatomopathologique du produit</strong>. Sortie le jour même ou le lendemain.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>CAT KB selon le tableau</h4>\n      <ul>\n        <li><strong><span class=\"kw-ci\">Grossesse</span> arrêtée</strong> (pas d’embryon visible, ou embryon sans AC, non expulsé) → expulsion par <span class=\"kw-ttt\">misoprostol</span> ou aspiration</li>\n        <li><strong><span class=\"kw-etio\">FCP</span> fœtus expulsé</strong> → abstention si expulsion complète, aspiration si débris trophoblastiques ou hémorragie ; <em>éviter <span class=\"kw-ttt\">misoprostol</span></em></li>\n      </ul>\n\n      <h4>Mesures associées systématiques</h4>\n      <ul>\n        <li><span class=\"kw-bio\">Groupe + Rhésus + RAI</span></li>\n        <li>Si <strong>Rh-</strong> et fœtus Rh+ ou inconnu : <span class=\"kw-ttt\">Ig anti-D</span> dans les <span class=\"kw-chiffre\">72 h</span></li>\n        <li><strong>Soutien psychologique</strong> — banale pour le médecin, source de traumatisme pour la femme</li>\n        <li>Information : <strong>aucune conséquence sur l’avenir obstétrical</strong> ; activité physique et voiture <span class=\"kw-alerte\">ne sont pas</span> des causes ❌</li>\n        <li><strong>Bilan étiologique</strong> seulement si <strong><span class=\"kw-chiffre\">≥ 3</span> épisodes consécutifs &lt; <span class=\"kw-chiffre\">14 SA</span></strong></li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Avortements spontanés à répétition (rang C).</strong> <span class=\"kw-chiffre\">≥ 3</span> FCS &lt; <span class=\"kw-chiffre\">14 SA</span> consécutives. Bilan : <span class=\"kw-bio\">caryotype des 2 conjoints</span> (translocations équilibrées), <span class=\"kw-bio\">anticoagulant circulant + anti-cardiolipine + anti-β2GP1</span> (SAPL), <span class=\"kw-imagerie\">écho 3D pelvienne</span> (malformation), <span class=\"kw-bio\">prélèvements bactério vaginaux/endocervicaux</span> (endométrite chronique), <span class=\"kw-bio\">bilan hormonal + glycémie</span>. Traitement préventif <span class=\"kw-ttt\">aspirine faible dose + HBPM préventive</span> uniquement efficace si SAPL.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — GEU · 23 — <span class=\"kw-ci\">Grossesse</span> normale · 43 — Hémorragie génitale chez la femme · 27 — Prévention des risques fœtaux</em></p>","frequence":0},{"id":"24-3","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître la prise en charge d’une grossesse extra-utérine","contenu":"<p>Cet objectif est <strong>traité intégralement dans l’item 25 — <span class=\"kw-ci\">Grossesse</span> extra-utérine</strong>. Synthèse opérationnelle ici pour la PEC de l’item 24.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Dogme.</strong> Toute <span class=\"kw-alerte\">femme en âge de procréer</span> avec douleur pelvienne et/ou métrorragies = <strong><span class=\"kw-etio\">GEU</span> jusqu’à preuve du contraire</strong>. Triade systématique : <strong>examen clinique + écho endovaginale + abdominale + β-hCG</strong>.\n      </div>\n\n      <h4>Tableau clinique typique</h4>\n      <ul>\n        <li><strong>Métrorragies :</strong> peu abondantes, foncées (<em>sépia</em>)</li>\n        <li><strong>Douleurs :</strong> latéralisées, sourdes avec accès plus intenses</li>\n        <li><strong><span class=\"kw-alerte\">TV</span> :</strong> col tonique fermé, utérus plus petit qu’attendu, <span class=\"kw-clinique\">masse</span> latéro-utérine, douleur au Douglas / mobilisation utérine</li>\n        <li><strong>Formes évoluées :</strong> scapulalgies (irritation diaphragmatique), <span class=\"kw-clinique\">malaise</span>, agitation</li>\n      </ul>\n\n      <h4><span class=\"kw-alerte\">Signes de gravité</span> = <span class=\"kw-alerte\">urgence</span> chirurgicale</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Hypotension, tachycardie, malaise</span></li>\n        <li><span class=\"kw-alerte\">Défense / contracture abdominale</span></li>\n        <li><span class=\"kw-alerte\">Hémopéritoine</span> à l’écho (Douglas, espace de Morisson)</li>\n      </ul>\n\n      <h4>Stratégie thérapeutique</h4>\n      <table >\n        <thead><tr><th>Option</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">Cœlioscopie</span></strong> (gold standard)</td><td>Patiente symptomatique, β-hCG &gt; 5000, <span class=\"kw-clinique\">masse</span> &gt; <span class=\"kw-chiffre\">4 cm</span>, AC visible, instabilité</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Laparotomie</span></strong></td><td>Hémopéritoine massif + <span class=\"kw-alerte\">choc</span>, CI à la <span class=\"kw-ttt\">cœlioscopie</span></td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Méthotrexate</span></strong> IM</td><td><span class=\"kw-etio\">GEU</span> paucisymptomatique, β-hCG &lt; 5000 (jusqu’à 10 000), pas d’AC, pas de <span class=\"kw-clinique\">masse</span> &gt; <span class=\"kw-chiffre\">4 cm</span>. <span class=\"kw-def\">Surveillance</span> hebdo β-hCG. Contraception <span class=\"kw-chiffre\">3 mois</span>.</td></tr>\n          <tr><td><strong>Abstention surveillée</strong></td><td>Asymptomatique + β-hCG &lt; 1000 + décroissance constante + observance</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Mesures associées</h4>\n      <ul>\n        <li><strong>Si Rh-</strong> : <span class=\"kw-ttt\">Ig anti-D</span> dans les <span class=\"kw-chiffre\">72 h</span></li>\n        <li><strong><span class=\"kw-def\">Dépistage</span> IST</strong> chez patiente + partenaire si séquelles d’IGH à la cœlio</li>\n        <li><strong>Récidive ≈ <span class=\"kw-chiffre\">20 %</span></strong> → écho précoce à <span class=\"kw-chiffre\">6 SA</span> pour <span class=\"kw-ci\">grossesse</span> suivante ⭐</li>\n        <li><strong><span class=\"kw-ttt\">Sevrage</span> tabagique</strong> systématique</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Item lié principal : 25 — <span class=\"kw-ci\">Grossesse</span> extra-utérine · 43 — Hémorragie génitale chez la femme · 162 — IST · 332 — États de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"24-4","rang":"A","rubrique":"Diagnostic","titre":"Connaître la prise en charge d’une hémorragie du deuxième ou du troisième trimestre","contenu":"<p>Les hémorragies du 2ᵉ / 3ᵉ trimestre sont une <span class=\"kw-alerte\">urgence obstétricale</span> imposant une <strong><span class=\"kw-alerte\">hospitalisation</span> immédiate</strong>. Trois diagnostics principaux : <span class=\"kw-etio\">placenta praevia</span>, <span class=\"kw-etio\">hématome rétroplacentaire</span> (<span class=\"kw-etio\">HRP</span>), causes plus rares (<span class=\"kw-etio\">hématome décidual marginal</span>, <span class=\"kw-etio\">rupture utérine</span>, <span class=\"kw-etio\">hémorragie de Benckiser</span>).</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Règle d’or.</strong> Le <span class=\"kw-alerte\">toucher vaginal est INTERDIT</span> tant qu’il existe une suspicion de <span class=\"kw-etio\">placenta praevia</span> (risque d’hémorragie cataclysmique). Le <span class=\"kw-alerte\">TV</span> ne sera autorisé qu’après une écho ayant éliminé le <span class=\"kw-etio\">placenta praevia</span>. <em>L’écho par voie vaginale, elle, reste autorisée.</em>\n      </div>\n\n      <h4>CAT systématique à l’admission</h4>\n      <ol>\n        <li><strong><span class=\"kw-alerte\">Hospitalisation</span></strong> 🏥 immédiate</li>\n        <li><span class=\"kw-bio\">Groupe + Rhésus + RAI</span> systématique ⭐ ; si Rh- et fœtus Rh+/inconnu → <span class=\"kw-ttt\">Ig anti-D</span> dans les <span class=\"kw-chiffre\">72 h</span></li>\n        <li><strong><span class=\"kw-alerte\">TV</span> <span class=\"kw-ci\">interdit</span></strong> tant que <span class=\"kw-etio\">placenta praevia</span> non écarté</li>\n        <li><span class=\"kw-imagerie\">Échographie obstétricale</span> : localisation placenta, recherche <span class=\"kw-etio\">HRP</span>, <span class=\"kw-def\">score</span> de Manning</li>\n        <li><strong>Enregistrement cardiotocographique (RCF + CU)</strong></li>\n        <li><strong><span class=\"kw-def\">Bilan préopératoire</span> complet</strong> : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">plaquettes</span>, <span class=\"kw-bio\">TP</span>/<span class=\"kw-bio\">TCA</span>, <span class=\"kw-bio\">fibrinogène</span>, RAI + consultation anesthésie</li>\n        <li><strong><span class=\"kw-bio\">BU</span> sur sondage évacuateur</strong> (sinon souillure) — <span class=\"kw-bio\">albuminurie</span> + → oriente <span class=\"kw-etio\">HRP</span></li>\n      </ol>\n\n      <h4>Orientation étiologique : <span class=\"kw-etio\">Placenta praevia</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-etio\">HRP</span></h4>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-etio\">Placenta praevia</span></th><th><span class=\"kw-etio\">HRP</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td>Multiparité, ATCD <span class=\"kw-ttt\">curetage</span> / <span class=\"kw-ttt\">chirurgie</span> utérine / césarienne</td><td>Âge &gt;<span class=\"kw-chiffre\"> 35 ans</span>, primipare, <span class=\"kw-etio\">tabac</span>, <span class=\"kw-clinique\">cocaïne</span> ⭐, <span class=\"kw-def\">HTA</span>, <span class=\"kw-etio\">prééclampsie</span></td></tr>\n          <tr><td><strong>Hémorragie</strong></td><td><strong>Abondante</strong>, inopinée, récidivante, <strong>sang rouge</strong>, <strong>coagulable</strong></td><td><strong>Peu abondante</strong>, <strong>noirâtre</strong>, <strong>incoagulable</strong></td></tr>\n          <tr><td><strong>Douleurs</strong></td><td>Absentes (uniquement CU)</td><td><strong>Brutales en coup de poignard</strong>, permanentes, dominent le tableau</td></tr>\n          <tr><td><strong>Utérus</strong></td><td>Indolore, souple entre CU</td><td><span class=\"kw-alerte\">Ventre de bois</span> — hypertonie permanente douloureuse</td></tr>\n          <tr><td><strong>Coagulation</strong></td><td>Normale</td><td><span class=\"kw-def\">CIVD</span></td></tr>\n          <tr><td><strong>Retentissement maternel</strong></td><td>En rapport avec l’hémorragie (FC↑, PA normale/↓)</td><td><strong>Sévère, sans rapport</strong> avec l’hémorragie : <span class=\"kw-alerte\">choc</span>, <span class=\"kw-clinique\">tachycardie</span>, PA variable parfois élevée</td></tr>\n          <tr><td><strong>RCF</strong></td><td>Fœtus vivant, AC bien perçue</td><td>Anomalies constantes (bradycardies) voire mort fœtale (formes complètes)</td></tr>\n          <tr><td><strong>Écho</strong></td><td>Placenta &lt; <span class=\"kw-chiffre\">50 mm</span> <span class=\"kw-radio\">de l’orifice interne du col, parfois recouvrant</span> ; <span class=\"kw-radio\">présentation pathologique (siège, transverse)</span></td><td><span class=\"kw-radio\">Placenta haut, à distance du segment inférieur</span> (signe indirect) ; <span class=\"kw-etio\">HRP</span> rarement visible sauf formes antérieures récentes</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-etio\">Placenta praevia</span> — PEC</h4>\n      <ul>\n        <li><strong>Si mal tolérée</strong> (aggravation / récidive cataclysmique) → <span class=\"kw-alerte\">césarienne pour sauvetage maternel en extrême urgence</span></li>\n        <li><strong>Si bien tolérée :</strong> repos au lit + bas de contention + remplissage ± transfusion + <span class=\"kw-def\">surveillance</span> ; <span class=\"kw-ttt\">tocolyse</span> (les CU sont probablement le facteur déclenchant, à condition d’avoir éliminé un <span class=\"kw-etio\">HRP</span>)</li>\n        <li><strong>Avant <span class=\"kw-chiffre\">34 SA</span></strong> : <span class=\"kw-ttt\">corticothérapie prénatale</span> ⭐ ± transfert maternité niveau 3</li>\n        <li><strong>Avant <span class=\"kw-chiffre\">32 SA</span> + naissance imminente</strong> : <span class=\"kw-ttt\">sulfate de magnésium</span></li>\n        <li><strong>Accouchement</strong> selon position : <strong>recouvrant</strong> → césarienne prophylactique &gt; <span class=\"kw-chiffre\">39 SA</span> ; <strong>non recouvrant</strong> → voie vaginale possible sous <span class=\"kw-def\">surveillance</span> stricte</li>\n      </ul>\n\n      <h4><span class=\"kw-etio\">HRP</span> — PEC</h4>\n      <div class=\"callout callout-danger\">\n        <strong>Toute suspicion d’<span class=\"kw-etio\">HRP</span> impose une naissance rapide</strong> par voie basse ou césarienne selon le contexte.\n      </div>\n      <ul>\n        <li><strong>Forme complète avec mort fœtale + <span class=\"kw-def\">CIVD</span> :</strong> expulsion par voie basse aussi rapide que possible. <span class=\"kw-alerte\">Rupture</span> des membranes si accessibles. Maturation cervicale par <span class=\"kw-ttt\">prostaglandines</span> si membranes inaccessibles. <span class=\"kw-ci\">Péridurale CI</span> en cas de <span class=\"kw-def\">CIVD</span> ⚠️ → <span class=\"kw-ttt\">antalgiques</span> parentéraux.</li>\n        <li><strong>Forme incomplète avec fœtus vivant :</strong> anomalies sévères du RCF → <span class=\"kw-alerte\">césarienne immédiate</span>. Diagnostic confirmé à l’intervention (caillots rétroplacentaires, aspect en cupule).</li>\n        <li><strong>Réa maternelle :</strong> oxygénation, remplissage, traitement de la <span class=\"kw-def\">CIVD</span> (PFC, <span class=\"kw-bio\">fibrinogène</span>, <span class=\"kw-bio\">plaquettes</span>), traitement de l’<span class=\"kw-def\">HTA</span> gravidique associée</li>\n        <li><strong><span class=\"kw-def\">Surveillance</span> avant et après expulsion :</strong> FC, PA, diurèse, globe utérin, <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">plaquettes</span>, hémato, coagulation + <span class=\"kw-bio\">fibrinogène</span></li>\n        <li><strong>Prévention <span class=\"kw-ci\">grossesse</span> ultérieure :</strong> arrêt <span class=\"kw-etio\">tabac</span> + cocaïne ; <span class=\"kw-ttt\">aspirine</span> empirique mal documentée dans cette indication</li>\n      </ul>\n\n      <h4>Autres causes — KB hors référentiel</h4>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Hématome décidual marginal</span> :</strong> décollement périphérique. Métrorragies peu abondantes, pas de souffrance fœtale. Écho diagnostique. <strong>Repos + <span class=\"kw-def\">surveillance</span> hospitalière</strong>.</li>\n        <li><strong><span class=\"kw-etio\">Hémorragie de Benckiser</span> :</strong> dilacération d’un <span class=\"kw-clinique\">vaisseau praevia</span> à la <span class=\"kw-alerte\">rupture</span> des membranes. <strong>État maternel conservé, c’est le fœtus qui saigne</strong>. Anomalies sévères du RCF immédiates. <span class=\"kw-def\">Mortalité</span> fœtale ≈ <span class=\"kw-chiffre\">100 %</span> → <span class=\"kw-alerte\">césarienne de sauvetage fœtal</span>.</li>\n        <li><strong><span class=\"kw-etio\">Rupture utérine</span></strong>, perte du bouchon muqueux (peu <span class=\"kw-etio\">hémorragique</span>)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — États de <span class=\"kw-alerte\">choc</span> · 213 — Anémie · 329 — Transfusion sanguine · 27 — Prévention des risques fœtaux</em></p>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/placenta-praevia","label":"Radiopaedia : Placenta praevia"},{"href":"https://radiopaedia.org/articles/retroplacental-haemorrhage","label":"Radiopaedia : Hématome rétroplacentaire"}]},{"id":"24-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la définition de l’hémorragie du post partum (HPP)","contenu":"<p>L’<span class=\"kw-def\">hémorragie du post-partum (HPP)</span> est définie de manière <strong>quantitative</strong> à partir des pertes sanguines mesurées dans les <span class=\"kw-chiffre\">24 h</span> suivant l’accouchement.</p>\n\n      <h4>Définitions à connaître</h4>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong>HPP</strong></td><td>Pertes sanguines <span class=\"kw-chiffre\">≥ 500 mL</span> dans les <strong><span class=\"kw-chiffre\">24 h</span> suivant l’accouchement</strong> (voie basse ou césarienne)</td></tr>\n          <tr><td><strong>HPP sévère</strong></td><td>Pertes <span class=\"kw-chiffre\">≥ 1000 mL</span> dans les <span class=\"kw-chiffre\">24 h</span></td></tr>\n          <tr><td><strong>Hémorragie de la délivrance</strong></td><td>HPP dans les <strong><span class=\"kw-chiffre\">2 h</span> post-accouchement par voie basse</strong> (période d’hémorragies immédiates les plus fréquentes)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Repères épidémiologiques</h4>\n      <ul>\n        <li><strong>Fréquence :</strong> <span class=\"kw-chiffre\">≈ 7 %</span> des accouchements (selon source de référence)</li>\n        <li><strong>1ʳᵉ cause de <span class=\"kw-def\">mortalité</span> maternelle</strong> dans le monde et en France</li>\n        <li><strong>Cause principale = atonie utérine</strong> (mécanisme le plus fréquent)</li>\n      </ul>\n\n      <h4>Mesure des pertes sanguines</h4>\n      <ul>\n        <li><strong>Sac de recueil sous-fessier gradué</strong> systématique à l’accouchement par voie basse — seule méthode fiable</li>\n        <li>L’estimation visuelle <strong>sous-estime</strong> systématiquement les pertes réelles ❌</li>\n        <li><strong>Évaluation horaire</strong> des pertes pendant les <span class=\"kw-chiffre\">2 h</span> post-accouchement (<span class=\"kw-def\">surveillance</span> en salle de naissance)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Mécanismes physiopathologiques.</strong> Les 4 « T » à retenir :\n        <ul>\n          <li><strong>Tonus</strong> — atonie utérine (cause n°1, ≈ <span class=\"kw-chiffre\">80 %</span>)</li>\n          <li><strong>Tissu</strong> — rétention placentaire (cotylédon, <span class=\"kw-etio\">placenta accreta</span>)</li>\n          <li><strong>Traumatisme</strong> — déchirure cervico-vaginale, <span class=\"kw-etio\">rupture utérine</span></li>\n          <li><strong>Thrombine</strong> — coagulopathie (<span class=\"kw-etio\">HRP</span>, <span class=\"kw-def\">CIVD</span>, traitement <span class=\"kw-ttt\">anticoagulant</span>)</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 329 — Transfusion sanguine · 332 — États de <span class=\"kw-alerte\">choc</span> · 213 — Anémie</em></p>","frequence":0},{"id":"24-6","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge d’une HPP","contenu":"<p>La PEC d’une HPP repose sur <strong>l’action en parallèle</strong> de trois équipes : obstétricale (gestes hémostatiques), anesthésique (réa maternelle), pharmacologique (utérotoniques). <strong>Chrono ⏱ : appel équipe + sac de recueil dès la 1ʳᵉ heure.</strong></p>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 620 250\" role=\"img\" aria-label=\"Frise d'escalade chronométrée de la prise en charge d'une hémorragie du post-partum. La réanimation maternelle et l'hémostase obstétricale se mènent en parallèle, jamais en série. À 0 minute : diagnostic dès 500 millilitres au sac de recueil, appel de l'obstétricien, de l'anesthésiste et de la sage-femme, chronomètre lancé. De 15 à 30 minutes : mesures obstétricales avec délivrance artificielle, révision utérine, examen sous valves et massage utérin, plus ocytocine intraveineuse en première intention. À 30 minutes en cas d'échec : sulprostone intraveineuse, Nalador, en deuxième intention. À 60 minutes en cas d'échec : embolisation artérielle si la patiente est stable, ou chirurgie d'hémostase de type B-Lynch et ligatures vasculaires, jusqu'à l'hystérectomie d'hémostase en ultime recours. En parallèle tout du long, la réanimation maternelle : deux voies veineuses, bilan NFS plaquettes TP TCA fibrinogène, remplissage et transfusion de culots, plasma et plaquettes, acide tranexamique avant 3 heures, prévention de l'hypothermie.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"700\">HPP — escalade chronométrée</text>\n          <text class=\"tx-muted\" x=\"310\" y=\"34\" text-anchor=\"middle\" font-size=\"10\">Hémostase obstétricale &amp; réa maternelle EN PARALLÈLE, jamais en série</text>\n\n          <rect class=\"fb-ok\" x=\"15\" y=\"50\" width=\"135\" height=\"84\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"82\" y=\"67\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\"><span class=\"kw-chiffre\">0 min</span> — Diagnostic</text>\n          <text class=\"tx-ok\" x=\"82\" y=\"84\" text-anchor=\"middle\" font-size=\"9\"><span class=\"kw-chiffre\">≥ 500 mL</span> au sac</text>\n          <text class=\"tx-ok\" x=\"82\" y=\"98\" text-anchor=\"middle\" font-size=\"9\">Appel obst.+anesth.+SF</text>\n          <text class=\"tx-ok\" x=\"82\" y=\"112\" text-anchor=\"middle\" font-size=\"9\">Chronomètre lancé</text>\n\n          <rect class=\"fb-amber\" x=\"160\" y=\"50\" width=\"135\" height=\"84\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"227\" y=\"67\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\"><span class=\"kw-chiffre\">15–30 min</span> — Obstétr.</text>\n          <text class=\"tx-amber\" x=\"227\" y=\"84\" text-anchor=\"middle\" font-size=\"9\">Délivr. artif. + révision</text>\n          <text class=\"tx-amber\" x=\"227\" y=\"98\" text-anchor=\"middle\" font-size=\"9\">Valves + massage utérin</text>\n          <text class=\"tx-amber\" x=\"227\" y=\"112\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">Oxytocine IV (1ʳᵉ int.)</text>\n\n          <rect class=\"fb-red\" x=\"305\" y=\"50\" width=\"135\" height=\"84\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"372\" y=\"67\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\"><span class=\"kw-chiffre\">30 min</span> ✗ — 2ᵉ ligne</text>\n          <text class=\"tx-red\" x=\"372\" y=\"87\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\">Sulprostone IV</text>\n          <text class=\"tx-red\" x=\"372\" y=\"101\" text-anchor=\"middle\" font-size=\"9\">(Nalador®, PGE2)</text>\n          <text class=\"tx-red\" x=\"372\" y=\"119\" text-anchor=\"middle\" font-size=\"8.5\">si échec oxytocine</text>\n\n          <rect class=\"fb-red\" x=\"450\" y=\"50\" width=\"155\" height=\"84\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"527\" y=\"67\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\"><span class=\"kw-chiffre\">60 min</span> ✗ — sauvetage</text>\n          <text class=\"tx-red\" x=\"527\" y=\"84\" text-anchor=\"middle\" font-size=\"9\">Embolisation (si stable)</text>\n          <text class=\"tx-red\" x=\"527\" y=\"98\" text-anchor=\"middle\" font-size=\"9\">ou chir. hémostase (B-Lynch)</text>\n          <text class=\"tx-red\" x=\"527\" y=\"112\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">→ hystérectomie (ultime)</text>\n\n          <line class=\"ln\" x1=\"150\" y1=\"92\" x2=\"158\" y2=\"92\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"160,92 152,88 152,96\"/>\n          <line class=\"ln\" x1=\"295\" y1=\"92\" x2=\"303\" y2=\"92\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"305,92 297,88 297,96\"/>\n          <line class=\"ln\" x1=\"440\" y1=\"92\" x2=\"448\" y2=\"92\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"450,92 442,88 442,96\"/>\n\n          <rect class=\"fb-band\" x=\"15\" y=\"150\" width=\"590\" height=\"50\" rx=\"6\"/>\n          <text class=\"tx-title\" x=\"310\" y=\"169\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">⇅ EN PARALLÈLE — <span class=\"kw-alerte\">Réanimation</span> maternelle</text>\n          <text class=\"tx-muted\" x=\"310\" y=\"186\" text-anchor=\"middle\" font-size=\"9\">2 VVP · <span class=\"kw-bio\">NFS</span>-plaq-TP-TCA-fibrinogène · remplissage + transfusion CGR/PFC/plaq · acide tranexamique &lt;<span class=\"kw-chiffre\"> 3 h</span> · prévention <span class=\"kw-clinique\">hypothermie</span></text>\n        </svg>\n        <figcaption>L’escalade est <strong>chronométrée</strong> : tout palier non maîtrisé en <span class=\"kw-chiffre\">30 min</span> fait passer au suivant. La <strong>bande grise</strong> = réa maternelle menée simultanément, pas après.</figcaption>\n      </figure>\n\n      <h4>Étape 1 — Diagnostic + appel d’équipe</h4>\n      <ul>\n        <li><strong>Diagnostic :</strong> <span class=\"kw-chiffre\">≥ 500 mL</span> au sac de recueil ou <span class=\"kw-alerte\">hémorragie active</span> inhabituelle</li>\n        <li><strong>Appel immédiat :</strong> obstétricien sénior + anesthésiste + sage-femme</li>\n        <li><strong>Chronomètre déclenché</strong> — toute HPP non maîtrisée à <span class=\"kw-chiffre\">30 min</span> devient sévère</li>\n      </ul>\n\n      <h4>Étape 2 — Mesures obstétricales (premières <span class=\"kw-chiffre\">30 min</span>)</h4>\n      <ol>\n        <li><strong>Délivrance artificielle</strong> si placenta non encore décollé</li>\n        <li><strong>Révision utérine</strong> systématique sous AG/péri (recherche rétention, <span class=\"kw-alerte\">rupture</span>)</li>\n        <li><strong>Examen sous valves</strong> du col + vagin → recherche de déchirure cervico-vaginale</li>\n        <li><strong>Massage utérin</strong> bimanuel ± <strong>vidange vésicale</strong> par sondage</li>\n        <li><strong>Sutures</strong> des déchirures vaginales/cervicales identifiées</li>\n      </ol>\n\n      <h4>Étape 3 — Utérotoniques</h4>\n      <table >\n        <thead><tr><th>Molécule</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Oxytocine</span> (Syntocinon®)</td><td><strong>1ʳᵉ intention</strong> — bolus IV puis entretien par perfusion. Max <span class=\"kw-chiffre\">40 UI</span> / <span class=\"kw-chiffre\">24 h</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Sulprostone</span> (Nalador®, prostaglandine PGE2)</td><td><strong>2ᵉ intention</strong> si échec d’oxytocine à <span class=\"kw-chiffre\">30 min</span>. IV en seringue électrique. <span class=\"kw-ci\">CI cardio-vasculaires</span> (coronaropathie, <span class=\"kw-def\">HTA</span> sévère)</td></tr>\n          <tr><td><span class=\"kw-ttt\">Misoprostol</span> (Cytotec®)</td><td>Alternative ou complément, voie intrarectale possible</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Étape 4 — <span class=\"kw-alerte\">Réanimation</span> maternelle parallèle</h4>\n      <ul>\n        <li><strong>2 VVP</strong> de bon calibre, monitorage continu (PA, FC, SpO₂, diurèse)</li>\n        <li><strong>Bilan en <span class=\"kw-alerte\">urgence</span> :</strong> <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">plaquettes</span>, <span class=\"kw-bio\">TP</span>/<span class=\"kw-bio\">TCA</span>, <span class=\"kw-bio\">fibrinogène</span>, groupe-Rh-RAI, HemoCue®</li>\n        <li><strong>Remplissage</strong> par cristalloïdes ; <strong>transfusion CGR + PFC + <span class=\"kw-bio\">plaquettes</span></strong> selon pertes et bilan</li>\n        <li><strong><span class=\"kw-bio\">Fibrinogène</span></strong> en cas de coagulopathie (objectif &gt; <span class=\"kw-chiffre\">2 g/L</span>)</li>\n        <li><strong>Acide tranexamique</strong> (Exacyl®) précocement (&lt; <span class=\"kw-chiffre\">3 h</span>) : <span class=\"kw-chiffre\">1 g IV</span></li>\n        <li><strong>Prévention <span class=\"kw-clinique\">hypothermie</span></strong> (couverture chauffante)</li>\n      </ul>\n\n      <h4>Étape 5 — Mesures de 2ᵉ ligne (HPP sévère non contrôlée)</h4>\n      <ul>\n        <li><strong>Embolisation artérielle</strong> par radiologie interventionnelle (si patiente stable)</li>\n        <li><strong>Tamponnement intra-utérin</strong> par ballon (Bakri)</li>\n        <li><strong><span class=\"kw-ttt\">Chirurgie</span> d’hémostase :</strong> ligature des artères utérines / hypogastriques, capitonnage utérin (B-Lynch)</li>\n        <li><strong>Hystérectomie d’hémostase</strong> en ultime recours (sauvetage maternel)</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>Algorithme temporel.</strong> <span class=\"kw-chiffre\">0 min</span> = diagnostic + appel · <span class=\"kw-chiffre\">15-30 min</span> = mesures obstétricales + oxytocine · <span class=\"kw-chiffre\">30 min</span> échec → <span class=\"kw-ttt\">sulprostone</span> · <span class=\"kw-chiffre\">60 min</span> échec → embolisation / <span class=\"kw-ttt\">chirurgie</span> d’hémostase. <strong>Réa et obstétrique en parallèle, jamais en série.</strong>\n      </div>\n\n      <h4><span class=\"kw-def\">Surveillance</span> post-HPP</h4>\n      <ul>\n        <li><span class=\"kw-def\">Surveillance</span> rapprochée en salle de naissance puis en suites de couches (FC, PA, globe utérin, lochies)</li>\n        <li><span class=\"kw-bio\">NFS</span> de contrôle, supplémentation en fer ± transfusion selon <span class=\"kw-bio\">hémoglobine</span></li>\n        <li><strong>Thromboprophylaxie</strong> par <span class=\"kw-ttt\">HBPM</span> (risque <span class=\"kw-def\">MTEV</span> majoré)</li>\n        <li><strong>Soutien psychologique</strong> : risque de syndrome post-traumatique</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 329 — Transfusion sanguine · 332 — États de <span class=\"kw-alerte\">choc</span> · 326 — Anti-thrombotiques · 213 — Anémie</em></p>","frequence":3},{"id":"24-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de prévention de l’HPP","contenu":"<p>La prévention de l’HPP repose sur <strong>3 piliers</strong> : identification des FR avant l’accouchement, <strong>délivrance dirigée systématique</strong>, <span class=\"kw-def\">surveillance</span> rapprochée du post-partum immédiat.</p>\n\n      <h4>Identification des FR</h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th><span class=\"kw-def\">Facteurs de risque</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Antécédents</strong></td><td>ATCD d’HPP, ATCD de césarienne, multiparité (<span class=\"kw-chiffre\">≥ 4</span>), grand âge maternel</td></tr>\n          <tr><td><strong>Distension utérine</strong></td><td><span class=\"kw-ci\">Grossesse</span> multiple, macrosomie, hydramnios</td></tr>\n          <tr><td><strong>Travail anormal</strong></td><td>Travail prolongé, déclenchement, dystocie, instrumentation, césarienne</td></tr>\n          <tr><td><strong>Placentaires</strong></td><td><span class=\"kw-etio\">Placenta praevia</span>, <span class=\"kw-etio\">placenta accreta</span>, <span class=\"kw-etio\">HRP</span>, rétention placentaire ancienne</td></tr>\n          <tr><td><strong>Coagulation</strong></td><td>Coagulopathie connue, traitement <span class=\"kw-ttt\">anticoagulant</span>, <span class=\"kw-etio\">prééclampsie</span> sévère, <span class=\"kw-etio\">HELLP</span></td></tr>\n          <tr><td><strong>Anémie pré-accouchement</strong></td><td>Tolérance hémodynamique moindre</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Délivrance dirigée — pivot de la prévention</h4>\n      <div class=\"callout callout-info\">\n        <strong>Définition.</strong> Administration d’un <span class=\"kw-ttt\">utérotonique</span> au moment du dégagement des épaules (voie basse) ou à l’extraction (césarienne).\n        <ul>\n          <li><strong>Molécule :</strong> <span class=\"kw-ttt\">oxytocine 5-10 UI IV lente</span> (ou IM)</li>\n          <li><strong>Alternative :</strong> <span class=\"kw-ttt\">carbétocine</span> (Pabal®) après césarienne</li>\n          <li><strong>Bénéfice :</strong> <span class=\"kw-ttt\">réduction</span> du risque d’HPP de <span class=\"kw-chiffre\">≈ 60 %</span></li>\n          <li><strong>Recommandation :</strong> à proposer à <strong>toutes les patientes</strong>, indépendamment des FR</li>\n        </ul>\n      </div>\n\n      <h4>Mesures organisationnelles</h4>\n      <ul>\n        <li><strong>Sac de recueil sous-fessier gradué</strong> systématique à l’accouchement par voie basse</li>\n        <li><strong><span class=\"kw-def\">Surveillance</span> des <span class=\"kw-chiffre\">2 h</span> post-partum</strong> en salle de naissance : globe utérin, pertes sanguines, constantes</li>\n        <li><strong>Protocole HPP</strong> écrit, affiché, connu de toutes les équipes</li>\n        <li><strong>Salle équipée</strong> en utérotoniques (oxytocine, sulprostone, <span class=\"kw-ttt\">misoprostol</span>)</li>\n        <li><strong>Disponibilité immédiate</strong> de PSL (CGR, PFC) et accès rapide à l’embolisation / <span class=\"kw-ttt\">chirurgie</span></li>\n      </ul>\n\n      <h4>Mesures spécifiques selon FR</h4>\n      <ul>\n        <li><strong>Anémie prénatale :</strong> correction par <span class=\"kw-ttt\">fer oral / IV</span> en fin de <span class=\"kw-ci\">grossesse</span> (objectif Hb <span class=\"kw-chiffre\">≥ 11 g/dL</span> à l’accouchement)</li>\n        <li><strong><span class=\"kw-etio\">Placenta accreta</span> suspecté :</strong> orientation vers maternité avec plateau technique chirurgical complet</li>\n        <li><strong>ATCD d’HPP :</strong> <span class=\"kw-def\">RCP</span> anténatale, choix d’une maternité adaptée, voie d’abord large</li>\n        <li><strong>Traitement <span class=\"kw-ttt\">anticoagulant</span> :</strong> protocole de relais péri-accouchement</li>\n      </ul>\n\n      <h4>Information de la patiente</h4>\n      <ul>\n        <li>Explication du <strong>risque <span class=\"kw-etio\">hémorragique</span> du post-partum</strong> et des mesures de prévention</li>\n        <li><strong>Consentement éclairé</strong> aux gestes de sauvetage (embolisation, hystérectomie)</li>\n        <li>Anticipation des situations à risque (<span class=\"kw-def\">RCP</span>, choix de la maternité)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 213 — Anémie · 326 — Anti-thrombotiques · 326 — <span class=\"kw-ttt\">Antalgiques</span> (péridurale)</em></p>","frequence":2},{"id":"24-8","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’hypertension artérielle (HTA) gravidique (HTAg)","contenu":"<p>Les troubles hypertensifs de la <span class=\"kw-ci\">grossesse</span> regroupent <strong>plusieurs entités à distinguer</strong>, en fonction du <strong>terme d’apparition</strong> et de la présence d’une <strong><span class=\"kw-bio\">protéinurie</span> / atteinte d’organe</strong>.</p>\n\n      <h4>Seuils tensionnels — Définition de l’<span class=\"kw-def\">HTA</span></h4>\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">HTA</span> pendant la <span class=\"kw-ci\">grossesse</span></strong> = PAS <span class=\"kw-chiffre\">≥ 140 mmHg</span> et/ou PAD <span class=\"kw-chiffre\">≥ 90 mmHg</span>, mesurée à <strong>2 reprises à au moins <span class=\"kw-chiffre\">4 h</span> d’intervalle</strong>, au repos, en position assise. <em><span class=\"kw-def\">HTA</span> sévère = PAS <span class=\"kw-chiffre\">≥ 160</span> et/ou PAD ≥ 110.</em>\n      </div>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 620 286\" role=\"img\" aria-label=\"Arbre de classification des troubles hypertensifs de la grossesse, définis par une PAS supérieure ou égale à 140 ou une PAD supérieure ou égale à 90, à deux reprises à 4 heures d'intervalle. Premier embranchement selon le terme. Si l'HTA est connue avant la grossesse ou apparaît avant 20 SA, c'est une HTA chronique, qui persiste au-delà de 6 semaines post-partum. Si l'HTA apparaît après 20 SA, on regarde la protéinurie et l'atteinte d'organe. Sans protéinurie et avec régression avant 6 semaines post-partum, c'est une HTA gravidique. Avec une protéinurie supérieure ou égale à 0,3 gramme par 24 heures ou une atteinte d'organe, c'est une prééclampsie. La prééclampsie peut se compliquer d'une éclampsie en cas de crise convulsive, ou d'un HELLP syndrome en cas d'hémolyse, cytolyse hépatique et thrombopénie. Note : une HTA chronique à laquelle s'ajoute une protéinurie après 20 SA définit une prééclampsie surajoutée, et environ 20 pour cent des HTA gravidiques évoluent vers une prééclampsie.\" style=\"height:auto;display:block;border-radius:8px\">\n          <rect class=\"fb-blue\" x=\"200\" y=\"10\" width=\"220\" height=\"44\" rx=\"6\"/>\n          <text class=\"tx-blue\" x=\"310\" y=\"29\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\"><span class=\"kw-etio\">HTA</span> en grossesse</text>\n          <text class=\"tx-blue\" x=\"310\" y=\"46\" text-anchor=\"middle\" font-size=\"9\">PAS <span class=\"kw-chiffre\">≥ 140</span> et/ou PAD ≥ 90 (×2,<span class=\"kw-chiffre\"> 4 h</span>)</text>\n\n          <line class=\"ln\" x1=\"310\" y1=\"54\" x2=\"310\" y2=\"64\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"155\" y1=\"64\" x2=\"465\" y2=\"64\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"155\" y1=\"64\" x2=\"155\" y2=\"78\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"155,80 150,72 160,72\"/>\n          <line class=\"ln\" x1=\"465\" y1=\"64\" x2=\"465\" y2=\"78\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"465,80 460,72 470,72\"/>\n          <text class=\"tx-muted\" x=\"150\" y=\"76\" text-anchor=\"end\" font-size=\"8.5\">&lt; 20 SA</text>\n          <text class=\"tx-muted\" x=\"470\" y=\"76\" text-anchor=\"start\" font-size=\"8.5\">&gt; 20 SA</text>\n\n          <rect class=\"fb-grey\" x=\"55\" y=\"80\" width=\"200\" height=\"30\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"155\" y=\"99\" text-anchor=\"middle\" font-size=\"9.5\">Connue avant grossesse / &lt; 20 SA</text>\n          <rect class=\"fb-grey\" x=\"320\" y=\"80\" width=\"270\" height=\"30\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"455\" y=\"99\" text-anchor=\"middle\" font-size=\"9.5\">Apparition après 20 SA</text>\n\n          <line class=\"ln\" x1=\"155\" y1=\"110\" x2=\"155\" y2=\"122\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"155,124 150,116 160,116\"/>\n\n          <rect class=\"fb-blue\" x=\"55\" y=\"124\" width=\"200\" height=\"48\" rx=\"6\"/>\n          <text class=\"tx-blue\" x=\"155\" y=\"144\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">HTA chronique</text>\n          <text class=\"tx-blue\" x=\"155\" y=\"161\" text-anchor=\"middle\" font-size=\"9\">persiste &gt; 6 sem post-partum</text>\n\n          <line class=\"ln\" x1=\"455\" y1=\"110\" x2=\"455\" y2=\"118\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"387\" y1=\"118\" x2=\"536\" y2=\"118\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"387\" y1=\"118\" x2=\"387\" y2=\"130\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"387,132 382,124 392,124\"/>\n          <line class=\"ln\" x1=\"536\" y1=\"118\" x2=\"536\" y2=\"130\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"536,132 531,124 541,124\"/>\n\n          <rect class=\"fb-amber\" x=\"320\" y=\"132\" width=\"135\" height=\"62\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"387\" y=\"151\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">HTA gravidique</text>\n          <text class=\"tx-amber\" x=\"387\" y=\"167\" text-anchor=\"middle\" font-size=\"8.5\"><span class=\"kw-bio\">protéinurie</span> négative</text>\n          <text class=\"tx-amber\" x=\"387\" y=\"181\" text-anchor=\"middle\" font-size=\"8.5\">régresse &lt; 6 sem PP</text>\n\n          <rect class=\"fb-red\" x=\"468\" y=\"132\" width=\"137\" height=\"62\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"536\" y=\"151\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">Prééclampsie</text>\n          <text class=\"tx-red\" x=\"536\" y=\"167\" text-anchor=\"middle\" font-size=\"8.5\">+ <span class=\"kw-bio\">protéinurie</span> <span class=\"kw-chiffre\">≥ 0,3 g</span>/<span class=\"kw-chiffre\">24 h</span></text>\n          <text class=\"tx-red\" x=\"536\" y=\"181\" text-anchor=\"middle\" font-size=\"8.5\">ou atteinte d’organe</text>\n\n          <line class=\"ln\" x1=\"536\" y1=\"194\" x2=\"536\" y2=\"202\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"501\" y1=\"202\" x2=\"572\" y2=\"202\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"501\" y1=\"202\" x2=\"501\" y2=\"214\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"501,216 496,208 506,208\"/>\n          <line class=\"ln\" x1=\"572\" y1=\"202\" x2=\"572\" y2=\"214\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"572,216 567,208 577,208\"/>\n\n          <rect class=\"fb-red\" x=\"468\" y=\"216\" width=\"66\" height=\"40\" rx=\"5\"/>\n          <text class=\"tx-red\" x=\"501\" y=\"233\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\">Éclampsie</text>\n          <text class=\"tx-red\" x=\"501\" y=\"246\" text-anchor=\"middle\" font-size=\"8\">+ <span class=\"kw-alerte\">convulsions</span></text>\n          <rect class=\"fb-red\" x=\"539\" y=\"216\" width=\"66\" height=\"40\" rx=\"5\"/>\n          <text class=\"tx-red\" x=\"572\" y=\"233\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\">HELLP</text>\n          <text class=\"tx-red\" x=\"572\" y=\"246\" text-anchor=\"middle\" font-size=\"8\">H · EL · LP</text>\n\n          <text class=\"tx-muted\" x=\"20\" y=\"232\" text-anchor=\"start\" font-size=\"9\">◗ HTA chronique +</text>\n          <text class=\"tx-muted\" x=\"20\" y=\"245\" text-anchor=\"start\" font-size=\"9\"><span class=\"kw-bio\">protéinurie</span> &gt; 20 SA</text>\n          <text class=\"tx-muted\" x=\"20\" y=\"258\" text-anchor=\"start\" font-size=\"9\">= PE surajoutée</text>\n          <text class=\"tx-muted\" x=\"20\" y=\"276\" text-anchor=\"start\" font-size=\"9\">◗ ~<span class=\"kw-chiffre\">20 %</span> HTAg → prééclampsie</text>\n        </svg>\n        <figcaption>Le <strong>pivot diagnostique</strong> : le terme (avant/après 20 SA) puis la <strong><span class=\"kw-bio\">protéinurie</span> / atteinte d’organe</strong>. HTAg pure = bon <span class=\"kw-def\">pronostic</span> ; <span class=\"kw-etio\">prééclampsie</span> = <span class=\"kw-alerte\">urgence</span> obstétricale.</figcaption>\n      </figure>\n\n      <h4><span class=\"kw-def\">Classification</span> des troubles hypertensifs gravidiques</h4>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">HTA</span> chronique</strong></td><td><span class=\"kw-def\">HTA</span> connue <strong>avant la <span class=\"kw-ci\">grossesse</span></strong> ou diagnostiquée <strong>avant <span class=\"kw-chiffre\">20 SA</span></strong> ; persiste après l’accouchement</td></tr>\n          <tr><td><strong><span class=\"kw-def\">HTA</span> gravidique (HTAg)</strong></td><td><span class=\"kw-def\">HTA</span> apparaissant <strong>après <span class=\"kw-chiffre\">20 SA</span></strong>, <strong>sans <span class=\"kw-bio\">protéinurie</span></strong>, qui régresse dans les <strong><span class=\"kw-chiffre\">6 semaines</span> post-partum</strong></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Prééclampsie</span></strong></td><td><span class=\"kw-def\">HTA</span> &gt; <span class=\"kw-chiffre\">20 SA</span> <strong>+ <span class=\"kw-bio\">protéinurie</span></strong> <span class=\"kw-chiffre\">≥ 0,3 g / 24 h</span> (ou rapport prot/créat &gt; <span class=\"kw-chiffre\">30 mg</span>/mmol) ; ou <span class=\"kw-def\">HTA</span> + atteinte d’organe (rénale, hépatique, neurologique, hématologique) ou foetale (<span class=\"kw-etio\">RCIU</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Prééclampsie surajoutée</span></strong></td><td><span class=\"kw-def\">HTA</span> chronique + apparition d’une <span class=\"kw-bio\">protéinurie</span> ou aggravation de la TA après <span class=\"kw-chiffre\">20 SA</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Éclampsie</span></strong></td><td>Survenue d’une <strong><span class=\"kw-clinique\">crise convulsive</span> généralisée</strong> sur <span class=\"kw-etio\">prééclampsie</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">HELLP</span> syndrome</strong></td><td>Hemolysis – Elevated Liver enzymes – Low Platelets — complication grave de la <span class=\"kw-etio\">prééclampsie</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Distinguer HTAg <span class=\"kw-bio\">vs</span> <span class=\"kw-etio\">Prééclampsie</span> — le pivot diagnostique</h4>\n      <ul>\n        <li><strong>HTAg pure :</strong> <span class=\"kw-def\">HTA</span> isolée &gt; <span class=\"kw-chiffre\">20 SA</span>, <strong><span class=\"kw-bio\">protéinurie</span> négative</strong>, pas d’atteinte d’organe → <span class=\"kw-def\">pronostic</span> globalement favorable</li>\n        <li><strong><span class=\"kw-etio\">Prééclampsie</span> :</strong> <span class=\"kw-def\">HTA</span> &gt; <span class=\"kw-chiffre\">20 SA</span> <strong>+ <span class=\"kw-bio\">protéinurie</span></strong> (<span class=\"kw-chiffre\">≥ 0,3 g/24 h</span>) ou atteinte d’organe → <span class=\"kw-alerte\">urgence obstétricale</span></li>\n        <li><strong>~ <span class=\"kw-chiffre\">20 %</span></strong> des HTAg isolées évoluent secondairement vers une <span class=\"kw-etio\">prééclampsie</span></li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège diagnostique.</strong> Une <strong><span class=\"kw-bio\">protéinurie</span> isolée sans <span class=\"kw-def\">HTA</span></strong> peut précéder l’<span class=\"kw-def\">HTA</span> dans certaines prééclampsies — c’est pourquoi la <span class=\"kw-bio\">bandelette urinaire</span> fait partie de <strong>chaque consultation prénatale</strong>.\n      </div>\n\n      <h4>Mesure tensionnelle correcte</h4>\n      <ul>\n        <li>Position <strong>assise</strong> ou semi-assise, après <span class=\"kw-chiffre\">5 min</span> de repos</li>\n        <li><strong>Brassard adapté</strong> au bras (sur-brassard si IMC élevé)</li>\n        <li><strong>Mesure aux 2 bras</strong> à la 1ʳᵉ consultation</li>\n        <li><strong>Confirmation à au moins <span class=\"kw-chiffre\">4 h</span> d’intervalle</strong> pour porter le diagnostic</li>\n        <li><strong><span class=\"kw-imagerie\">MAPA</span></strong> ou auto-mesure utiles en cas de doute (effet blouse blanche)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-etio\">HTA</span> · 344 — HTA gravidique et prééclampsie · 23 — <span class=\"kw-ci\">Grossesse</span> normale · 27 — Prévention des risques fœtaux</em></p>","frequence":2},{"id":"24-9","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la fréquence de l’HTAg","contenu":"<p>L’<span class=\"kw-def\">HTA</span> pendant la <span class=\"kw-ci\">grossesse</span> est <strong>fréquente</strong> et constitue l’une des principales causes de morbi-<span class=\"kw-def\">mortalité</span> maternelle et fœtale dans les pays développés.</p>\n\n      <h4>Données épidémiologiques</h4>\n      <table >\n        <thead><tr><th>Entité</th><th>Fréquence</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Troubles hypertensifs de la <span class=\"kw-ci\">grossesse</span> (toutes formes)</strong></td><td><span class=\"kw-chiffre\">10-15 %</span> des grossesses</td></tr>\n          <tr><td><strong><span class=\"kw-def\">HTA</span> gravidique (HTAg)</strong></td><td><span class=\"kw-chiffre\">5-10 %</span> des grossesses</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Prééclampsie</span></strong></td><td><span class=\"kw-chiffre\">2-3 %</span> des grossesses en France (<span class=\"kw-chiffre\">5-7 %</span> primipares, <span class=\"kw-chiffre\">1-2 %</span> multipares)</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Prééclampsie</span> sévère</strong></td><td><span class=\"kw-chiffre\">~ 1 %</span> des grossesses</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Éclampsie</span></strong></td><td><span class=\"kw-chiffre\">1/2 000 à 1/3 000</span> grossesses</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">HELLP</span> syndrome</strong></td><td><span class=\"kw-chiffre\">~ 0,5 %</span> des grossesses, complique <span class=\"kw-chiffre\">10-20 %</span> des prééclampsies sévères</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Mortalité</span> maternelle</h4>\n      <ul>\n        <li>La <strong><span class=\"kw-etio\">prééclampsie</span>/<span class=\"kw-etio\">éclampsie</span></strong> est la <strong>2ᵉ cause de <span class=\"kw-def\">mortalité</span> maternelle</strong> en France (après l’HPP)</li>\n        <li><strong>1ʳᵉ cause de <span class=\"kw-def\">mortalité</span> maternelle</strong> par cause directe dans les pays développés selon certaines séries</li>\n        <li><strong>~ 30 décès maternels / an</strong> en France attribuables aux troubles hypertensifs</li>\n      </ul>\n\n      <h4><span class=\"kw-def\">Mortalité</span> et morbidité fœtales</h4>\n      <ul>\n        <li><strong>1ʳᵉ cause d’accouchement prématuré induit</strong> (~ <span class=\"kw-chiffre\">15 %</span> des AP &lt; <span class=\"kw-chiffre\">32 SA</span>)</li>\n        <li><strong>1ʳᵉ cause de <span class=\"kw-etio\">RCIU</span></strong> d’origine vasculaire</li>\n        <li>Risque de <strong>mort fœtale in utero</strong> par <span class=\"kw-etio\">HRP</span> ou insuffisance placentaire sévère</li>\n      </ul>\n\n      <h4><span class=\"kw-def\">Facteurs de risque</span> épidémiologiques</h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td>Primiparité, âge &gt;<span class=\"kw-chiffre\"> 35 ans</span> (ou &lt; 18), <span class=\"kw-etio\">obésité</span>, origine afro-caribéenne</td></tr>\n          <tr><td><strong>Antécédents</strong></td><td>ATCD personnel de <span class=\"kw-etio\">prééclampsie</span> (RR × 7), ATCD familial de <span class=\"kw-etio\">prééclampsie</span> au 1ᵉʳ degré</td></tr>\n          <tr><td><strong>Pathologies associées</strong></td><td><span class=\"kw-def\">HTA</span> chronique, <span class=\"kw-def\">diabète</span> préexistant, néphropathie chronique, <span class=\"kw-def\">lupus</span> / SAPL, thrombophilie</td></tr>\n          <tr><td><strong><span class=\"kw-ci\">Grossesse</span></strong></td><td><span class=\"kw-ci\">Grossesse</span> multiple, grossesse issue de don d’ovocyte, intervalle long entre grossesses</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-etio\">HTA</span> · 344 — HTA gravidique et prééclampsie · 255 — <span class=\"kw-def\">Diabète gestationnel</span> · 22 — Maladies rares</em></p>","frequence":0},{"id":"24-10","rang":"B","rubrique":"Examens complémentaires","titre":"Savoir prescrire et interpréter les examens complémentaires en cas d’HTA gravidique","contenu":"<p>Le bilan d’une <span class=\"kw-def\">HTA</span> gravidique a <strong>3 objectifs</strong> : (1) <strong>distinguer HTAg pure <span class=\"kw-bio\">vs</span> <span class=\"kw-etio\">prééclampsie</span></strong> (recherche <span class=\"kw-bio\">protéinurie</span> + atteintes d’organe), (2) <strong>évaluer la sévérité</strong>, (3) <strong>surveiller le bien-être fœtal</strong>.</p>\n\n      <h4>Bilan maternel — biologie systématique</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Protéinurie des 24 h</span> (ou rapport prot/créat sur miction)</td><td>≥ <span class=\"kw-chiffre\">0,3 g/24 h</span> ou prot/créat &gt; <span class=\"kw-chiffre\">30 mg</span>/mmol = <strong><span class=\"kw-etio\">prééclampsie</span></strong></td></tr>\n          <tr><td><span class=\"kw-bio\">Bandelette urinaire</span></td><td>À chaque consultation prénatale — <span class=\"kw-def\">dépistage</span> rapide</td></tr>\n          <tr><td><span class=\"kw-bio\">NFS plaquettes</span></td><td><strong>Thrombopénie &lt; <span class=\"kw-chiffre\">100 G/L</span></strong> = <span class=\"kw-def\">critère de</span> sévérité (<span class=\"kw-etio\">HELLP</span>), <span class=\"kw-alerte\">hémolyse</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Ionogramme + créatinine + urée</span></td><td><strong><span class=\"kw-def\">Insuffisance rénale aiguë</span></strong> (créat &gt; <span class=\"kw-chiffre\">90 µmol/L</span> ou doublement)</td></tr>\n          <tr><td><span class=\"kw-bio\">Uricémie</span></td><td>Élevée dans la <span class=\"kw-etio\">prééclampsie</span> (corrélée à la sévérité)</td></tr>\n          <tr><td><span class=\"kw-bio\">ASAT / ALAT / LDH / Bilirubine</span></td><td>Cytolyse hépatique = critère <span class=\"kw-etio\">HELLP</span> ; <span class=\"kw-bio\">LDH</span> ↑ + bili ↑ = hémolyse</td></tr>\n          <tr><td><span class=\"kw-bio\">Haptoglobine + frottis sanguin (schizocytes)</span></td><td>Recherche d’hémolyse (<span class=\"kw-etio\">HELLP</span>)</td></tr>\n          <tr><td><span class=\"kw-bio\">TP / TCA / Fibrinogène</span></td><td>Recherche <span class=\"kw-def\">CIVD</span> si sévère, avant péridurale</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Bilan fœtal — <span class=\"kw-def\">surveillance</span> du retentissement</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">Échographie obstétricale</span></td><td>Estimation du <strong>poids fœtal</strong> (<span class=\"kw-etio\">RCIU</span> si &lt; 10ᵉ percentile), <strong>liquide amniotique</strong> (oligoamnios)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Doppler ombilical et utérin</span></td><td>Évaluation de la <strong>perfusion placentaire</strong> ; <span class=\"kw-radio\">diastole nulle / inversée</span> = <span class=\"kw-alerte\">signe de gravité</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">RCF / Cardiotocographie</span></td><td>Recherche d’anomalies du rythme — signe de souffrance fœtale</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Examens selon contexte / sévérité</h4>\n      <ul>\n        <li><strong>Fond d’œil</strong> si <span class=\"kw-def\">HTA</span> sévère ou signes neurologiques (recherche d’<span class=\"kw-clinique\">œdème</span> papillaire, hémorragies)</li>\n        <li><strong><span class=\"kw-bio\">ECG</span> + écho cardiaque</strong> si <span class=\"kw-def\">HTA</span> sévère ou prolongée</li>\n        <li><strong><span class=\"kw-imagerie\">TDM</span> / <span class=\"kw-imagerie\">IRM</span> cérébrale</strong> si signes neurologiques (recherche d’<strong><span class=\"kw-clinique\">œdème</span> cérébral postérieur réversible / <span class=\"kw-def\">PRES</span> syndrome</strong>, hémorragie)</li>\n        <li><strong>Bilan thrombophilie</strong> en cas de <span class=\"kw-etio\">prééclampsie</span> précoce ou récidivante (en dehors de la <span class=\"kw-ci\">grossesse</span>)</li>\n      </ul>\n\n      <h4>Tableau <span class=\"kw-ttt\">biologique</span> <span class=\"kw-etio\">HELLP</span></h4>\n      <div class=\"callout callout-danger\">\n        <strong>Critères <span class=\"kw-etio\">HELLP</span></strong> :\n        <ul>\n          <li><strong>H</strong> — Hémolyse : <span class=\"kw-bio\">LDH</span> ↑ &gt; 600, <span class=\"kw-bio\">haptoglobine</span> effondrée, schizocytes</li>\n          <li><strong>EL</strong> — Elevated Liver enzymes : <span class=\"kw-bio\">ASAT</span>/<span class=\"kw-bio\">ALAT</span> &gt; <strong>2 × normale</strong></li>\n          <li><strong>LP</strong> — Low Platelets : <span class=\"kw-bio\">plaquettes</span> <strong>&lt; <span class=\"kw-chiffre\">100 G/L</span></strong></li>\n        </ul>\n        Complication majeure : risque d’<strong>hématome sous-capsulaire du foie</strong> (<span class=\"kw-alerte\">rupture</span> cataclysmique).\n      </div>\n\n      <h4>Algorithme décisionnel simplifié</h4>\n      <ol>\n        <li><strong><span class=\"kw-def\">HTA</span> &gt; <span class=\"kw-chiffre\">20 SA</span> + <span class=\"kw-bio\">protéinurie</span> négative</strong> → HTAg pure → <span class=\"kw-def\">surveillance</span>, bilan toutes les <span class=\"kw-chiffre\">2 semaines</span></li>\n        <li><strong><span class=\"kw-def\">HTA</span> &gt; <span class=\"kw-chiffre\">20 SA</span> + <span class=\"kw-bio\">protéinurie</span> <span class=\"kw-chiffre\">≥ 0,3 g/24 h</span></strong> → <span class=\"kw-etio\">prééclampsie</span> → <span class=\"kw-alerte\">hospitalisation</span></li>\n        <li><strong>Apparition de signes de sévérité</strong> (cf. obj-11) → <span class=\"kw-alerte\">surveillance maternité niveau 3</span> + bilan complet</li>\n      </ol>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 254 — Nutrition et <span class=\"kw-ci\">grossesse</span> · 224 — <span class=\"kw-etio\">HTA</span> · 344 — HTA gravidique et prééclampsie · 213 — Anémie · 167 — Hépatites virales</em></p>","frequence":3},{"id":"24-11","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications de l’HTAg","contenu":"<p>L’<span class=\"kw-def\">HTA</span> gravidique expose à des <strong>complications maternelles</strong> (<span class=\"kw-etio\">prééclampsie</span> et ses formes graves) et <strong>fœtales</strong> (<span class=\"kw-etio\">RCIU</span>, prématurité induite, <span class=\"kw-etio\">MFIU</span>).</p>\n\n      <h4>Complications maternelles</h4>\n      <table >\n        <thead><tr><th>Complication</th><th>Mécanisme / clinique</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Prééclampsie</span></strong></td><td>~ <span class=\"kw-chiffre\">20 %</span> des HTAg pures évoluent vers <span class=\"kw-etio\">prééclampsie</span> (<span class=\"kw-def\">HTA</span> + <span class=\"kw-bio\">protéinurie</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\">Éclampsie</span></td><td><span class=\"kw-clinique\">Crise convulsive</span> tonico-clonique généralisée sur <span class=\"kw-etio\">prééclampsie</span> — peut survenir <em>avant, pendant ou après</em> l’accouchement (jusqu’à <span class=\"kw-chiffre\">7 jours</span> post-partum)</td></tr>\n          <tr><td><span class=\"kw-alerte\">HELLP syndrome</span></td><td>Hémolyse + cytolyse hépatique + thrombopénie ; risque <strong>d’hématome sous-capsulaire du foie</strong></td></tr>\n          <tr><td><span class=\"kw-alerte\">Hématome rétroplacentaire (HRP)</span></td><td>Décollement prématuré → <span class=\"kw-def\">CIVD</span> + souffrance fœtale ; <em>fréquemment associé à l’HTAg / <span class=\"kw-etio\">prééclampsie</span></em></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Insuffisance rénale aiguë</span></strong></td><td><span class=\"kw-def\">NTA</span>, voire <span class=\"kw-clinique\">nécrose</span> corticale ; favorisée par hypovolémie + <span class=\"kw-def\">CIVD</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Œdème aigu pulmonaire</span> (<span class=\"kw-def\">OAP</span>)</strong></td><td>Surcharge + altération de la perméabilité capillaire</td></tr>\n          <tr><td><strong><span class=\"kw-def\">AVC</span> <span class=\"kw-etio\">hémorragique</span></strong></td><td>Cause principale de <span class=\"kw-def\">mortalité</span> maternelle dans la <span class=\"kw-etio\">prééclampsie</span> sévère</td></tr>\n          <tr><td><strong><span class=\"kw-def\">PRES</span> syndrome</strong> (<span class=\"kw-clinique\">œdème</span> cérébral postérieur réversible)</td><td><span class=\"kw-clinique\">Céphalées</span> + troubles visuels + crises ; <span class=\"kw-imagerie\">IRM</span> caractéristique</td></tr>\n          <tr><td><strong><span class=\"kw-def\">CIVD</span></strong></td><td>Surtout en cas de <span class=\"kw-etio\">HELLP</span>, <span class=\"kw-etio\">HRP</span> ou <span class=\"kw-alerte\">hémorragie massive</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Complications fœtales</h4>\n      <table >\n        <thead><tr><th>Complication</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">RCIU</span> (retard de croissance intra-utérin)</strong></td><td>Insuffisance vasculaire utéroplacentaire ; surtout en cas de <span class=\"kw-etio\">prééclampsie</span> précoce</td></tr>\n          <tr><td><strong>Prématurité induite</strong></td><td>Accouchement déclenché pour sauvetage maternel ou fœtal</td></tr>\n          <tr><td><strong>Souffrance fœtale aiguë</strong></td><td>Anomalies du RCF, oligoamnios, <span class=\"kw-imagerie\">doppler</span> ombilical pathologique</td></tr>\n          <tr><td><strong>Mort fœtale in utero (<span class=\"kw-etio\">MFIU</span>)</strong></td><td>Insuffisance placentaire sévère ou <span class=\"kw-etio\">HRP</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Complications du post-partum à connaître</h4>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Éclampsie</span> du post-partum</strong> — possible jusqu’à <strong><span class=\"kw-chiffre\">7 jours</span> après l’accouchement</strong> ⚠️</li>\n        <li><strong>Persistance de l’<span class=\"kw-def\">HTA</span></strong> au-delà de <span class=\"kw-chiffre\">6 semaines</span> → réévaluer en cardio (<span class=\"kw-def\">HTA</span> chronique sous-jacente ?)</li>\n        <li><strong><span class=\"kw-def\">Thrombose veineuse profonde</span> / EP</strong> — risque <span class=\"kw-def\">MTEV</span> majoré</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>Triade de l’<span class=\"kw-etio\">éclampsie</span> imminente.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Céphalées intenses</span> (en casque, frontales)</li>\n          <li><span class=\"kw-alerte\">Troubles visuels</span> (phosphènes, flou visuel, scotomes)</li>\n          <li><span class=\"kw-alerte\">Douleur épigastrique en barre</span> (signe de Chaussier — distension de la capsule de Glisson)</li>\n        </ul>\n        <strong>Hyperréflexie ostéo-tendineuse</strong> souvent associée.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-etio\">HTA</span> · 344 — HTA gravidique et prééclampsie · 332 — États de <span class=\"kw-alerte\">choc</span> · 105 — Épilepsies · 213 — Anémie</em></p>","frequence":0},{"id":"24-12","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les éléments de sévérité","contenu":"<p>L’identification des <strong><span class=\"kw-def\">critères de</span> sévérité</strong> conditionne la <strong>conduite à tenir immédiate</strong> : <span class=\"kw-alerte\">hospitalisation</span>, <span class=\"kw-def\">surveillance</span> rapprochée, indication d’accouchement.</p>\n\n      <h4><span class=\"kw-def\">Critères de</span> sévérité maternels — Cliniques</h4>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-def\">HTA</span> sévère.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">PAS ≥ 160 mmHg</span> et/ou <span class=\"kw-alerte\">PAD ≥ 110 mmHg</span></li>\n        </ul>\n        <strong>Signes fonctionnels d’<span class=\"kw-etio\">éclampsie</span> imminente.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Céphalées intenses, rebelles aux antalgiques</span></li>\n          <li><span class=\"kw-alerte\">Troubles visuels :</span> phosphènes, flou, scotomes, amaurose</li>\n          <li><span class=\"kw-alerte\">Douleur épigastrique en barre (signe de Chaussier)</span></li>\n          <li><span class=\"kw-alerte\">Nausées / vomissements</span></li>\n          <li><span class=\"kw-alerte\">Hyperréflexie ostéo-tendineuse</span></li>\n          <li><span class=\"kw-clinique\">Crise convulsive</span> = <span class=\"kw-etio\">éclampsie</span> déclarée</li>\n        </ul>\n        <strong>Signes d’hypoperfusion / <span class=\"kw-alerte\">défaillance</span>.</strong>\n        <ul>\n          <li><strong><span class=\"kw-clinique\">Oligurie</span></strong> (&lt; <span class=\"kw-chiffre\">500 mL</span>/<span class=\"kw-chiffre\">24 h</span>)</li>\n          <li><strong><span class=\"kw-def\">OAP</span></strong> (<span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">crépitants</span>)</li>\n          <li><strong>Troubles de la conscience</strong></li>\n        </ul>\n      </div>\n\n      <h4><span class=\"kw-def\">Critères de</span> sévérité — Biologiques</h4>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Seuil de sévérité</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-bio\">Protéinurie</span></strong></td><td>&gt; <span class=\"kw-chiffre\">3 g / 24 h</span> (<span class=\"kw-etio\">prééclampsie</span> sévère)</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Créatininémie</span></strong></td><td>&gt; <span class=\"kw-chiffre\">90 µmol/L</span> ou doublement de la créat de base</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Plaquettes</span></strong></td><td>&lt; <span class=\"kw-chiffre\">100 G/L</span> (<span class=\"kw-etio\">HELLP</span>)</td></tr>\n          <tr><td><strong>Transaminases (<span class=\"kw-bio\">ASAT</span>/<span class=\"kw-bio\">ALAT</span>)</strong></td><td>&gt; <span class=\"kw-chiffre\">2 × normale</span> (<span class=\"kw-etio\">HELLP</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">LDH</span> + <span class=\"kw-bio\">bilirubine</span></strong></td><td>↑ + <span class=\"kw-bio\">haptoglobine</span> ↓ = hémolyse (<span class=\"kw-etio\">HELLP</span>)</td></tr>\n          <tr><td><strong>Uricémie</strong></td><td>Élevée et corrélée à la sévérité</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Critères de</span> sévérité — Fœtaux</h4>\n      <ul>\n        <li><strong><span class=\"kw-etio\">RCIU</span> sévère</strong> &lt; 3ᵉ percentile</li>\n        <li><strong>Oligoamnios</strong> sévère (index amniotique <span class=\"kw-chiffre\">≤ 5</span>)</li>\n        <li><strong><span class=\"kw-imagerie\">Doppler</span> ombilical pathologique</strong> : <span class=\"kw-alerte\">diastole nulle ou reverse-flow</span></li>\n        <li><strong>Anomalies sévères du RCF</strong></li>\n        <li><strong>Mort fœtale in utero</strong></li>\n      </ul>\n\n      <h4>Critères selon le terme</h4>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Prééclampsie</span> précoce &lt; <span class=\"kw-chiffre\">32-34 SA</span></strong> → forme habituellement plus sévère, <span class=\"kw-def\">pronostic</span> moins bon</li>\n        <li><strong><span class=\"kw-etio\">Prééclampsie</span> tardive <span class=\"kw-chiffre\">≥ 34 SA</span></strong> → <span class=\"kw-def\">pronostic</span> globalement meilleur</li>\n      </ul>\n\n      <h4>Conduite à tenir devant un <span class=\"kw-def\">critère de</span> sévérité</h4>\n      <ol>\n        <li><strong><span class=\"kw-alerte\">Hospitalisation</span> immédiate</strong> en maternité de niveau adapté (3 si &lt; <span class=\"kw-chiffre\">32 SA</span>)</li>\n        <li><strong>Bilan complet</strong> maternel + fœtal (cf. obj-9)</li>\n        <li><strong>Traitement antihypertenseur</strong> en <span class=\"kw-alerte\">urgence</span> si <span class=\"kw-def\">HTA</span> sévère (cf. obj-12)</li>\n        <li><strong>Sulfate de magnésium</strong> en prévention de l’<span class=\"kw-etio\">éclampsie</span> si signes neurologiques</li>\n        <li><strong><span class=\"kw-ttt\">Corticothérapie</span> prénatale</strong> &lt; <span class=\"kw-chiffre\">34 SA</span> (préparation à l’accouchement éventuel)</li>\n        <li><strong>Discussion d’extraction fœtale</strong> selon terme et tolérance maternelle</li>\n      </ol>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-etio\">HTA</span> · 344 — HTA gravidique et prééclampsie · 332 — États de <span class=\"kw-alerte\">choc</span> · 105 — Épilepsies · 359 — <span class=\"kw-alerte\">Détresse</span> respiratoire aiguë</em></p>","frequence":0},{"id":"24-13","rang":"B","rubrique":"Prise en charge","titre":"Savoir prescrire les mesures de repos et le traitement antihypertenseur chez une femme enceinte","contenu":"<p>La PEC de l’HTAg associe <strong>mesures non médicamenteuses</strong>, <strong>antihypertenseurs adaptés à la <span class=\"kw-ci\">grossesse</span></strong>, et <strong>traitement spécifique des formes sévères</strong> (sulfate de Mg, accouchement).</p>\n\n      <h4>Mesures non médicamenteuses</h4>\n      <table >\n        <thead><tr><th>Mesure</th><th>Recommandation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Repos relatif</strong></td><td><strong>Pas d’alitement strict</strong> ❌ (majore le risque de <span class=\"kw-def\">MTEV</span>) — <strong>repos modulé</strong>, arrêt de travail si pénible</td></tr>\n          <tr><td><strong>Arrêt de travail</strong></td><td>Selon situation et terme</td></tr>\n          <tr><td><strong>Régime</strong></td><td><strong>Pas de régime hyposodé</strong> ❌ — peut aggraver l’hypovolémie maternelle</td></tr>\n          <tr><td><strong>Bas de contention</strong></td><td>Prévention de la <span class=\"kw-def\">MTEV</span> en cas de repos</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Surveillance</span> domicile</strong></td><td>Auto-mesure tensionnelle, recherche signes d’alerte</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Antihypertenseurs autorisés pendant la <span class=\"kw-ci\">grossesse</span></h4>\n      <table >\n        <thead><tr><th>Classe</th><th>Molécules</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Antihypertenseurs centraux</strong></td><td><span class=\"kw-ttt\">Alpha-méthyldopa</span> (Aldomet®)</td><td><strong>1ʳᵉ intention historique</strong>, recul d’utilisation pendant la <span class=\"kw-ci\">grossesse</span>, bonne tolérance fœtale</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Inhibiteurs calciques</span></strong></td><td><span class=\"kw-ttt\">Nicardipine</span> (Loxen®), <span class=\"kw-ttt\">Nifédipine</span></td><td><strong>1ʳᵉ intention</strong> orale et IV ; rapide d’action, utilisable en aigu</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Bêtabloquants</span></strong></td><td><span class=\"kw-ttt\">Labétalol</span> (Trandate®, α + β-)</td><td><strong>1ʳᵉ intention</strong> particulièrement en aigu IV ; alternative orale</td></tr>\n          <tr><td><strong>Vasodilatateurs périphériques</strong></td><td><span class=\"kw-ttt\">Clonidine</span></td><td>Réserve</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Antihypertenseurs CONTRE-INDIQUÉS pendant la <span class=\"kw-ci\">grossesse</span></h4>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-ci\">Contre-indications</span> absolues — à connaître ⭐.</strong>\n        <ul>\n          <li><span class=\"kw-ci\">IEC</span> (énalapril, <span class=\"kw-ttt\">ramipril</span>...) — <strong>fœtotoxicité</strong> : oligoamnios, <span class=\"kw-def\">IRA</span> fœtale, malformations rénales</li>\n          <li><span class=\"kw-ci\">ARA II / sartans</span> (<span class=\"kw-ttt\">losartan</span>, <span class=\"kw-ttt\">valsartan</span>...) — <strong>même toxicité que les <span class=\"kw-ttt\">IEC</span></strong></li>\n          <li><span class=\"kw-ci\">Inhibiteurs directs de la rénine</span> (aliskirène)</li>\n          <li><span class=\"kw-ci\">Diurétiques</span> (sauf indication spécifique : <span class=\"kw-def\">OAP</span>, IC) — risque d’hypoperfusion utéroplacentaire</li>\n        </ul>\n      </div>\n\n      <h4>Objectifs tensionnels</h4>\n      <table >\n        <thead><tr><th>Situation</th><th>Objectif PA</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">HTA</span> non sévère</strong></td><td>PAS &lt; <span class=\"kw-chiffre\">150 mmHg</span> et PAD &lt; <span class=\"kw-chiffre\">100 mmHg</span> (objectif large, pas trop bas pour préserver la perfusion utéroplacentaire)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">HTA</span> sévère (PAS <span class=\"kw-chiffre\">≥ 160</span> ou PAD ≥ 110)</strong></td><td><span class=\"kw-ttt\">Réduction</span> progressive vers PAS 140-150 / PAD 90-100 — <strong>pas de chute brutale</strong> ⚠️ (risque d’hypoperfusion fœtale)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Stratégie thérapeutique selon sévérité</h4>\n      <ul>\n        <li><strong>HTAg modérée :</strong> traitement oral (alpha-méthyldopa OU nicardipine OU <span class=\"kw-ttt\">labétalol</span>), monothérapie en 1ʳᵉ intention</li>\n        <li><strong>HTAg sévère (<span class=\"kw-alerte\">urgence</span>) :</strong> <span class=\"kw-alerte\">hospitalisation</span> + <span class=\"kw-ttt\">nicardipine IV à la seringue électrique</span> ou <span class=\"kw-ttt\">labétalol IV</span></li>\n        <li><strong>Bithérapie</strong> si <span class=\"kw-def\">HTA</span> non contrôlée par la monothérapie</li>\n      </ul>\n\n      <h4>Sulfate de magnésium — prévention de l’<span class=\"kw-etio\">éclampsie</span></h4>\n      <div class=\"callout callout-warn\">\n        <strong>Indications du sulfate de Mg ⭐.</strong>\n        <ul>\n          <li><strong><span class=\"kw-etio\">Prééclampsie</span> sévère</strong> avec signes neurologiques (<span class=\"kw-clinique\">céphalées</span>, phosphènes, hyperréflexie)</li>\n          <li><strong><span class=\"kw-etio\">Éclampsie</span></strong> (traitement curatif)</li>\n          <li><strong>Neuroprotection fœtale</strong> avant <span class=\"kw-chiffre\">32 SA</span> en cas de naissance imminente</li>\n        </ul>\n        <strong>Posologie :</strong> dose de charge <span class=\"kw-chiffre\">4 g</span> IVL en <span class=\"kw-chiffre\">20 min</span> puis entretien <span class=\"kw-chiffre\">1 g/h</span>.<br>\n        <strong><span class=\"kw-def\">Surveillance</span> :</strong> ROT (disparition = surdosage), FR (&gt;<span class=\"kw-chiffre\"> 12/min</span>), diurèse.<br>\n        <strong>Antidote :</strong> gluconate de calcium IV.\n      </div>\n\n      <h4>Indications d’extraction fœtale</h4>\n      <ul>\n        <li><strong>HTAg non sévère :</strong> accouchement à partir de <strong><span class=\"kw-chiffre\">37-38 SA</span></strong></li>\n        <li><strong><span class=\"kw-etio\">Prééclampsie</span> modérée :</strong> accouchement à <strong><span class=\"kw-chiffre\">37 SA</span></strong></li>\n        <li><strong><span class=\"kw-etio\">Prééclampsie</span> sévère :</strong> accouchement <strong>quel que soit le terme</strong> (<span class=\"kw-alerte\">urgence</span> si retentissement maternel ou fœtal)</li>\n        <li><strong><span class=\"kw-etio\">Éclampsie</span> / <span class=\"kw-etio\">HELLP</span> / <span class=\"kw-etio\">HRP</span> :</strong> accouchement en <span class=\"kw-alerte\">urgence</span> (césarienne le plus souvent)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-etio\">HTA</span> · 326 — Prescription des antihypertenseurs · 344 — HTA gravidique et prééclampsie · 359 — <span class=\"kw-alerte\">Détresse</span> respiratoire aiguë</em></p>","frequence":4},{"id":"24-14","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Savoir surveiller une HTAg","contenu":"<p>La <span class=\"kw-def\">surveillance</span> d’une HTAg doit être <strong>rapprochée et structurée</strong>, à la fois <strong>maternelle</strong> (recherche d’<span class=\"kw-clinique\">évolution</span> vers une <span class=\"kw-etio\">prééclampsie</span>, d’une sévérité) et <strong>fœtale</strong> (croissance, bien-être, perfusion).</p>\n\n      <h4>Rythme de <span class=\"kw-def\">surveillance</span> — HTAg pure (non sévère, sans <span class=\"kw-bio\">protéinurie</span>)</h4>\n      <table >\n        <thead><tr><th>Volet</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Consultations</strong></td><td><strong>Toutes les <span class=\"kw-chiffre\">1 à 2 semaines</span></strong> selon <span class=\"kw-clinique\">évolution</span></td></tr>\n          <tr><td><strong>Auto-mesure tensionnelle</strong></td><td>Plusieurs fois/jour à domicile, carnet de <span class=\"kw-def\">surveillance</span></td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Bandelette urinaire</span></strong></td><td>À chaque consultation — <span class=\"kw-def\">dépistage</span> de l’apparition d’une <span class=\"kw-bio\">protéinurie</span></td></tr>\n          <tr><td><strong>Biologie</strong></td><td><span class=\"kw-bio\">NFS</span> <span class=\"kw-bio\">plaquettes</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">ASAT</span>/<span class=\"kw-bio\">ALAT</span>, <span class=\"kw-bio\">uricémie</span>, <span class=\"kw-bio\">protéinurie</span>/<span class=\"kw-chiffre\">24 h</span> <strong>toutes les <span class=\"kw-chiffre\">2 semaines</span></strong></td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Échographie</span> fœtale</strong></td><td><strong>Toutes les <span class=\"kw-chiffre\">3-4 semaines</span></strong> — croissance, <span class=\"kw-imagerie\">doppler</span> ombilical/utérin</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Critères imposant une <span class=\"kw-alerte\">hospitalisation</span></h4>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Hospitalisation</span> immédiate si :</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">HTA sévère</span> (PAS <span class=\"kw-chiffre\">≥ 160</span> ou PAD ≥ 110)</li>\n          <li><span class=\"kw-alerte\">Apparition de protéinurie</span> <span class=\"kw-chiffre\">≥ 0,3 g/24 h</span></li>\n          <li><span class=\"kw-alerte\">Signes neurologiques</span> (<span class=\"kw-clinique\">céphalées</span>, troubles visuels)</li>\n          <li><span class=\"kw-alerte\">Signes biologiques</span> de <span class=\"kw-etio\">HELLP</span> ou <span class=\"kw-def\">IRA</span></li>\n          <li><span class=\"kw-etio\">RCIU</span> ou <span class=\"kw-imagerie\">doppler</span> ombilical pathologique</li>\n          <li><strong>Mauvaise observance</strong>, <span class=\"kw-def\">surveillance</span> ambulatoire impossible</li>\n        </ul>\n      </div>\n\n      <h4>Auto-<span class=\"kw-def\">surveillance</span> — éducation de la patiente</h4>\n      <ul>\n        <li><strong>Auto-mesure tensionnelle</strong> matin + soir + en cas de symptôme</li>\n        <li><strong>Signes d’alerte</strong> à connaître et signaler en <span class=\"kw-alerte\">urgence</span> : <span class=\"kw-clinique\">céphalées</span>, phosphènes, douleur épigastrique, <span class=\"kw-clinique\">nausées</span>, diminution des mouvements fœtaux</li>\n        <li><strong>Carnet de <span class=\"kw-def\">surveillance</span></strong> avec chiffres tensionnels et symptômes</li>\n        <li><strong>Numéro d’<span class=\"kw-alerte\">urgence</span></strong> de la maternité</li>\n      </ul>\n\n      <h4><span class=\"kw-def\">Surveillance</span> fœtale — <span class=\"kw-def\">critères de</span> bien-être</h4>\n      <ul>\n        <li><strong>Mouvements actifs fœtaux</strong> ressentis par la mère</li>\n        <li><strong><span class=\"kw-imagerie\">Échographie</span> :</strong> croissance, biométrie (poids estimé), quantité de liquide amniotique</li>\n        <li><strong><span class=\"kw-imagerie\">Doppler</span> ombilical :</strong> recherche d’une diminution du flux diastolique, signe d’insuffisance placentaire</li>\n        <li><strong>RCF / Cardiotocographie</strong> en <span class=\"kw-alerte\">hospitalisation</span> si <span class=\"kw-def\">HTA</span> mal contrôlée ou signes de sévérité</li>\n      </ul>\n\n      <h4>Lieux de prise en charge</h4>\n      <ul>\n        <li><strong>HTAg modérée bien contrôlée :</strong> <span class=\"kw-def\">surveillance</span> ambulatoire en consultation</li>\n        <li><strong>HTAg sévère ou <span class=\"kw-etio\">prééclampsie</span> :</strong> <span class=\"kw-alerte\">hospitalisation</span> en maternité de niveau adapté</li>\n        <li><strong>Avant <span class=\"kw-chiffre\">32 SA</span> + retentissement fœtal :</strong> <strong>maternité de niveau 3</strong> (réa néonatale)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 224 — <span class=\"kw-etio\">HTA</span> · 344 — HTA gravidique et prééclampsie</em></p>","frequence":1},{"id":"24-15","rang":"B","rubrique":"Prise en charge","titre":"Connaître la conduite à tenir après l’accouchement en cas d’HTAg","contenu":"<p>Le post-partum est une période <strong>à haut risque</strong> chez les patientes ayant présenté une HTAg/<span class=\"kw-etio\">prééclampsie</span>. L’<span class=\"kw-etio\">éclampsie</span> peut survenir <strong>jusqu’à <span class=\"kw-chiffre\">7 jours</span> après l’accouchement</strong>. La <span class=\"kw-def\">surveillance</span> et le traitement doivent être poursuivis.</p>\n\n      <h4><span class=\"kw-def\">Surveillance</span> immédiate (premières <span class=\"kw-chiffre\">48 h</span>)</h4>\n      <ul>\n        <li><strong>Monitorage tensionnel</strong> rapproché (toutes les <span class=\"kw-chiffre\">4 h</span>, puis allégé selon <span class=\"kw-clinique\">évolution</span>)</li>\n        <li><strong><span class=\"kw-def\">Surveillance</span> neurologique</strong> : ROT, <span class=\"kw-clinique\">céphalées</span>, troubles visuels (risque d’<span class=\"kw-etio\">éclampsie</span> post-partum jusqu’à <strong><span class=\"kw-chiffre\">7 jours</span></strong>)</li>\n        <li><strong>Diurèse</strong> horaire pendant <span class=\"kw-chiffre\">24 h</span> (<span class=\"kw-def\">surveillance</span> fonction rénale)</li>\n        <li><strong>Bilan <span class=\"kw-ttt\">biologique</span></strong> à <span class=\"kw-chiffre\">H6</span>, H24, H48 : <span class=\"kw-bio\">NFS</span> <span class=\"kw-bio\">plaquettes</span>, créat, <span class=\"kw-bio\">ASAT</span>/<span class=\"kw-bio\">ALAT</span>, <span class=\"kw-bio\">LDH</span> (recherche aggravation <span class=\"kw-etio\">HELLP</span>)</li>\n        <li><strong>Poursuite du sulfate de Mg</strong> <span class=\"kw-chiffre\">24 h</span> après l’accouchement si <span class=\"kw-etio\">prééclampsie</span> sévère / <span class=\"kw-etio\">éclampsie</span></li>\n      </ul>\n\n      <h4><span class=\"kw-clinique\">Évolution</span> attendue de l’<span class=\"kw-def\">HTA</span></h4>\n      <table >\n        <thead><tr><th>Phase</th><th>Évolution typique</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-chiffre\">J0</span>-J3</strong></td><td>Possibilité d’aggravation transitoire de l’<span class=\"kw-def\">HTA</span> (pic des résistances vasculaires)</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">J3</span>-J10</strong></td><td>Diurèse augmentée, baisse progressive de la TA</td></tr>\n          <tr><td><strong>J10-S6</strong></td><td>Normalisation tensionnelle attendue dans l’HTAg pure</td></tr>\n          <tr><td><strong>&gt; <span class=\"kw-chiffre\">6 semaines</span></strong></td><td>Persistance de l’<span class=\"kw-def\">HTA</span> → suspicion d’<strong><span class=\"kw-def\">HTA</span> chronique sous-jacente</strong> (<span class=\"kw-def\">réévaluation</span> cardio)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Adaptation du traitement antihypertenseur</h4>\n      <ul>\n        <li><strong>Poursuite</strong> de l’antihypertenseur en post-partum, en adaptant la posologie à la TA</li>\n        <li><strong>Décroissance progressive</strong> sur <span class=\"kw-chiffre\">2-6 semaines</span> en cas de normalisation</li>\n        <li><strong>Possibilité d’élargir l’éventail</strong> de molécules après l’accouchement (les <span class=\"kw-ttt\">IEC</span> redeviennent utilisables — <strong>captopril, énalapril</strong> sont compatibles avec l’<span class=\"kw-ci\">allaitement</span>)</li>\n      </ul>\n\n      <h4><span class=\"kw-ci\">Allaitement</span></h4>\n      <table >\n        <thead><tr><th>Molécule</th><th>Compatibilité allaitement</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Alpha-méthyldopa</span></td><td>Compatible</td></tr>\n          <tr><td><span class=\"kw-ttt\">Nicardipine</span></td><td>Compatible</td></tr>\n          <tr><td><span class=\"kw-ttt\">Labétalol</span></td><td>Compatible (préférer aux <span class=\"kw-ttt\">bêtabloquants</span> liposolubles)</td></tr>\n          <tr><td><span class=\"kw-ttt\">Captopril / Énalapril</span></td><td>Compatible avec l’<span class=\"kw-ci\">allaitement</span> (en post-partum uniquement, jamais pendant la grossesse)</td></tr>\n          <tr><td><span class=\"kw-ci\">Diurétiques</span></td><td>Peuvent diminuer la lactation</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Prévention thromboembolique</h4>\n      <ul>\n        <li>Le post-partum d’une HTAg / <span class=\"kw-etio\">prééclampsie</span> est un <strong>contexte à risque accru de <span class=\"kw-def\">MTEV</span></strong></li>\n        <li><strong>Thromboprophylaxie par <span class=\"kw-ttt\">HBPM</span></strong> à discuter (durée <span class=\"kw-chiffre\">6 semaines</span> selon FR associés)</li>\n        <li><strong>Bas de contention</strong> + mobilisation précoce</li>\n      </ul>\n\n      <h4>Consultation post-natale (<span class=\"kw-chiffre\">6-8 semaines</span>)</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Réévaluation</span> tensionnelle</strong> — confirmer la résolution ou identifier une <span class=\"kw-def\">HTA</span> chronique</li>\n        <li><strong>Bilan rénal complet</strong> (créat, <span class=\"kw-bio\">protéinurie</span>/<span class=\"kw-chiffre\">24 h</span>)</li>\n        <li><strong>Information sur le risque cardiovasculaire à long terme</strong> (cf. obj-16)</li>\n        <li><strong>Discussion des grossesses ultérieures</strong> (cf. obj-15)</li>\n        <li><strong>Choix contraceptif</strong> tenant compte des FR vasculaires (privilégier méthodes non-œstrogéniques)</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-etio\">Éclampsie</span> du post-partum.</strong> Survenue possible jusqu’à <strong><span class=\"kw-chiffre\">7 jours</span> après l’accouchement</strong>. <span class=\"kw-def\">Surveillance</span> neurologique active + maintien du sulfate de Mg <span class=\"kw-chiffre\">24 h</span> après la naissance dans les prééclampsies sévères.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-etio\">HTA</span> · 326 — Anti-thrombotiques · 344 — HTA gravidique et prééclampsie · 36 — Contraception</em></p>","frequence":0},{"id":"24-16","rang":"A","rubrique":"Prise en charge","titre":"Connaître la prévention lors des grossesses ultérieures","contenu":"<p>Après une HTAg ou une <span class=\"kw-etio\">prééclampsie</span>, le risque de <strong>récidive lors d’une <span class=\"kw-ci\">grossesse</span> ultérieure est significatif</strong> : <span class=\"kw-chiffre\">10-20 %</span> pour la <span class=\"kw-etio\">prééclampsie</span> (jusqu’à <span class=\"kw-chiffre\">40 %</span> en cas de PE précoce sévère). La <strong>prévention par <span class=\"kw-ttt\">aspirine</span></strong> est le pivot.</p>\n\n      <h4>Risque de récidive</h4>\n      <table >\n        <thead><tr><th>Contexte</th><th>Risque de récidive</th></tr></thead>\n        <tbody>\n          <tr><td><strong>HTAg pure (non compliquée)</strong></td><td>Risque modéré de récidive d’HTAg, faible risque de <span class=\"kw-etio\">prééclampsie</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Prééclampsie</span> modérée à terme</strong></td><td><span class=\"kw-chiffre\">~ 10-15 %</span> de récidive</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Prééclampsie</span> sévère ou précoce (&lt; <span class=\"kw-chiffre\">34 SA</span>)</strong></td><td><span class=\"kw-chiffre\">~ 30-40 %</span> de récidive</td></tr>\n          <tr><td><strong>Antécédent d’<span class=\"kw-etio\">éclampsie</span> ou <span class=\"kw-etio\">HELLP</span></strong></td><td>Risque élevé de récidive (idem PE sévère)</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-ttt\">Aspirine</span> faible dose — pivot de la prévention</h4>\n      <div class=\"callout callout-info\">\n        <strong>Indications de l’<span class=\"kw-ttt\">aspirine 100-160 mg/jour</span> ⭐.</strong>\n        <ul>\n          <li><strong>ATCD personnel de <span class=\"kw-etio\">prééclampsie</span></strong> (surtout précoce ou sévère)</li>\n          <li><strong><span class=\"kw-def\">HTA</span> chronique</strong> ou <strong>néphropathie chronique</strong></li>\n          <li><strong><span class=\"kw-def\">Diabète</span> préexistant</strong> (<span class=\"kw-def\">DT1</span> ou <span class=\"kw-def\">DT2</span>)</li>\n          <li><strong><span class=\"kw-def\">Lupus</span> / SAPL</strong> connu</li>\n          <li>Présence de <strong><span class=\"kw-chiffre\">≥ 2</span> FR modérés</strong> : 1ʳᵉ <span class=\"kw-ci\">grossesse</span>, âge &gt;<span class=\"kw-chiffre\"> 35-40 ans</span>, IMC <span class=\"kw-chiffre\">≥ 35,</span> ATCD familial PE, intervalle long entre grossesses, grossesse multiple, origine afro-caribéenne</li>\n        </ul>\n        <strong>Modalités :</strong>\n        <ul>\n          <li><strong>Début :</strong> entre 12 et <span class=\"kw-chiffre\">16 SA</span> (au plus tard avant <span class=\"kw-chiffre\">20 SA</span>)</li>\n          <li><strong>Prise vespérale</strong> (efficacité maximale démontrée)</li>\n          <li><strong>Arrêt à <span class=\"kw-chiffre\">35-36 SA</span></strong> (avant l’accouchement)</li>\n          <li><strong><span class=\"kw-ttt\">Réduction</span> du risque de PE de <span class=\"kw-chiffre\">40-60 %</span></strong> dans les indications validées</li>\n        </ul>\n      </div>\n\n      <h4>Autres mesures préventives</h4>\n      <table >\n        <thead><tr><th>Mesure</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Consultation préconceptionnelle</strong></td><td>Bilan complet de la pathologie sous-jacente, optimisation du traitement (substitution <span class=\"kw-ttt\">IEC</span>/ARA II → alpha-méthyldopa/<span class=\"kw-ttt\">labétalol</span>), équilibration du <span class=\"kw-def\">diabète</span>, <span class=\"kw-clinique\">perte de poids</span></td></tr>\n          <tr><td><strong>Supplémentation en calcium</strong></td><td><span class=\"kw-ttt\">1 g/jour</span> recommandée chez les femmes à apport calcique faible (efficacité modérée)</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Sevrage</span> tabagique</strong></td><td>Important — bien que paradoxalement le <span class=\"kw-etio\">tabac</span> diminue le risque de PE, il majore le risque de <span class=\"kw-etio\">HRP</span> et <span class=\"kw-etio\">RCIU</span></td></tr>\n          <tr><td><strong>Contrôle pondéral</strong></td><td><span class=\"kw-ttt\">Réduction</span> de l’IMC avant la conception si <span class=\"kw-etio\">obésité</span></td></tr>\n          <tr><td><strong>Bilan thrombophilie</strong></td><td>Si <span class=\"kw-etio\">prééclampsie</span> précoce / sévère : recherche SAPL, déficit en protéine S, protéine C, antithrombine, mutation Leiden, prothrombine</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Surveillance</span> rapprochée de la <span class=\"kw-ci\">grossesse</span> suivante</h4>\n      <ul>\n        <li><strong>Consultations rapprochées</strong> dès le 1ᵉʳ trimestre</li>\n        <li><strong><span class=\"kw-bio\">Bandelette urinaire</span> + TA</strong> à chaque consultation</li>\n        <li><strong><span class=\"kw-imagerie\">Échographie</span> + <span class=\"kw-imagerie\">doppler</span> utérin à <span class=\"kw-chiffre\">22-24 SA</span></strong> — recherche d’<strong>incisure protodiastolique</strong> ou index de pulsatilité élevé (signes prédictifs de PE)</li>\n        <li><strong><span class=\"kw-def\">Suivi</span> conjoint</strong> obstétricien + médecin référent de la pathologie sous-jacente (cardio, néphro, internal med)</li>\n        <li><strong>Maternité de niveau adapté</strong> au risque</li>\n      </ul>\n\n      <h4>Mesures NON recommandées</h4>\n      <ul>\n        <li><strong>Repos au lit</strong> ❌ — pas d’efficacité préventive prouvée, majore le risque <span class=\"kw-def\">MTEV</span></li>\n        <li><strong>Régime hyposodé</strong> ❌ — pas d’efficacité, peut aggraver l’hypovolémie</li>\n        <li><strong>Vitamines C/E</strong> ❌ — pas d’efficacité (essais négatifs)</li>\n        <li><strong><span class=\"kw-ttt\">HBPM</span> systématique</strong> ❌ — uniquement si thrombophilie diagnostiquée</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 224 — <span class=\"kw-etio\">HTA</span> · 326 — Anti-thrombotiques · 344 — HTA gravidique et prééclampsie</em></p>","frequence":0},{"id":"24-17","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les complications à long terme de l’HTAg","contenu":"<p>L’<span class=\"kw-def\">HTA</span> gravidique et la <span class=\"kw-etio\">prééclampsie</span> ne sont pas des « événements isolés » de la <span class=\"kw-ci\">grossesse</span> : elles constituent un <strong>marqueur de risque cardiovasculaire à long terme</strong> pour la femme, justifiant un <strong><span class=\"kw-def\">suivi</span> médical au long cours</strong>.</p>\n\n      <h4>Risques cardiovasculaires à long terme</h4>\n      <table >\n        <thead><tr><th>Risque</th><th>Magnitude</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">HTA</span> chronique</strong></td><td>RR <span class=\"kw-chiffre\">× 2-4</span> <span class=\"kw-bio\">vs</span> population générale ; ~ <span class=\"kw-chiffre\">20-30 %</span> des HTAg/PE développent une <span class=\"kw-def\">HTA</span> chronique dans les <span class=\"kw-chiffre\">10-15 ans</span></td></tr>\n          <tr><td><strong>Maladie coronarienne / <span class=\"kw-def\">IDM</span></strong></td><td>RR <span class=\"kw-chiffre\">× 2</span> à long terme (jusqu’à × 8 si PE précoce sévère)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">AVC</span></strong></td><td>RR <span class=\"kw-chiffre\">× 1,5-2</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Insuffisance rénale chronique</span></strong></td><td>Risque accru, notamment en cas de PE sévère ou récidivante</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Diabète de type 2</span></strong></td><td>Risque modérément augmenté (<span class=\"kw-def\">terrain</span> métabolique partagé)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Mortalité</span> cardiovasculaire</strong></td><td>RR <span class=\"kw-chiffre\">× 2</span> globalement</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Mécanismes proposés</h4>\n      <ul>\n        <li><strong>Marqueur d’un <span class=\"kw-def\">terrain</span> prédisposant</strong> (insulinorésistance, dysfonction endothéliale, terrain <span class=\"kw-etio\">inflammatoire</span>)</li>\n        <li><strong>Effet propre</strong> de l’<span class=\"kw-def\">HTA</span>/PE sur l’endothélium et la fonction rénale</li>\n        <li><strong>Persistance de <span class=\"kw-def\">facteurs de risque</span></strong> partagés (<span class=\"kw-etio\">surpoids</span>, <span class=\"kw-etio\">sédentarité</span>)</li>\n      </ul>\n\n      <h4>Conséquences à très long terme — Spécifiques</h4>\n      <ul>\n        <li><strong>Risque accru de <span class=\"kw-etio\">prééclampsie</span></strong> dans les grossesses ultérieures (cf. obj-15)</li>\n        <li><strong><span class=\"kw-def\">Insuffisance rénale chronique</span> :</strong> <span class=\"kw-def\">dépistage</span> par <span class=\"kw-bio\">créatininémie</span> + <span class=\"kw-bio\">protéinurie</span> tous les <span class=\"kw-chiffre\">1-2 ans</span>, surtout si PE sévère ou avec atteinte rénale</li>\n        <li><strong>Hématome sous-capsulaire hépatique</strong> en post-<span class=\"kw-etio\">HELLP</span> : généralement résolutif mais risque de séquelles hépatiques</li>\n        <li><strong>Persistance de séquelles neurologiques</strong> exceptionnelles après <span class=\"kw-etio\">éclampsie</span> ou <span class=\"kw-def\">PRES</span> syndrome</li>\n      </ul>\n\n      <h4><span class=\"kw-def\">Suivi</span> médical au long cours — recommandations</h4>\n      <div class=\"callout callout-info\">\n        <strong>Plan de <span class=\"kw-def\">suivi</span> systématique après HTAg / <span class=\"kw-etio\">prééclampsie</span>.</strong>\n        <ul>\n          <li><strong>Consultation à <span class=\"kw-chiffre\">6-8 semaines</span> :</strong> bilan tensionnel + <span class=\"kw-bio\">bilan rénal</span> complet</li>\n          <li><strong>Consultation à <span class=\"kw-chiffre\">3-6 mois</span> :</strong> confirmation de la normalisation</li>\n          <li><strong><span class=\"kw-def\">Suivi</span> annuel</strong> par le médecin traitant : TA, IMC, <span class=\"kw-bio\">glycémie à jeun</span>, <span class=\"kw-bio\">bilan lipidique</span>, créat + <span class=\"kw-bio\">protéinurie</span></li>\n          <li><strong>Évaluation cardiologique</strong> rapprochée si signes ou ATCD de PE sévère</li>\n        </ul>\n        <strong>Éducation à long terme.</strong>\n        <ul>\n          <li>Activité physique régulière</li>\n          <li>Alimentation équilibrée (régime méditerranéen)</li>\n          <li>Maintien d’un poids normal</li>\n          <li><span class=\"kw-ttt\">Sevrage</span> tabagique impératif</li>\n          <li><span class=\"kw-def\">Dépistage</span> des autres <span class=\"kw-etio\">FRCV</span> (<span class=\"kw-def\">diabète</span>, <span class=\"kw-etio\">dyslipidémie</span>)</li>\n        </ul>\n      </div>\n\n      <h4>Complications fœtales à long terme</h4>\n      <ul>\n        <li><strong>Enfants nés prématurément</strong> (PE → AP induit) : risque accru de troubles du neurodéveloppement, séquelles respiratoires</li>\n        <li><strong>Enfants avec <span class=\"kw-etio\">RCIU</span></strong> : risque augmenté à l’âge adulte d’<span class=\"kw-def\">HTA</span>, <span class=\"kw-def\">diabète</span>, maladie cardiovasculaire (hypothèse de Barker)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-etio\">HTA</span> · 253 — <span class=\"kw-etio\">Obésité</span> · 222 — FDR cardiovasculaire · 254 — Nutrition</em></p>","frequence":0},{"id":"24-18","rang":"A","rubrique":"Epidémiologie","titre":"Définir et diagnostiquer une menace d’accouchement prématuré","contenu":"<p>La <span class=\"kw-def\">menace d’accouchement prématuré (MAP)</span> = association de <strong>modifications cervicales + contractions utérines régulières et douloureuses</strong>, survenant entre <strong><span class=\"kw-chiffre\">22 SA</span> et <span class=\"kw-chiffre\">36 SA</span> + <span class=\"kw-chiffre\">6 jours</span></strong>. C’est l’une des principales causes d’<span class=\"kw-alerte\">hospitalisation</span> pendant la <span class=\"kw-ci\">grossesse</span>.</p>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 620 276\" role=\"img\" aria-label=\"Frise des seuils gestationnels de la menace d'accouchement prématuré. L'axe va de 22 à 41 semaines d'aménorrhée. Trois fenêtres d'intervention se lisent au-dessus de l'axe : le sulfate de magnésium en neuroprotection fœtale et l'orientation en maternité de type 3 s'appliquent avant 32 SA ; la corticothérapie prénatale par bétaméthasone ou dexaméthasone s'applique avant 34 SA ; la tocolyse de 48 heures, le temps d'organiser le transfert in utero et de laisser agir les corticoïdes, s'arrête à 34 SA. Sous l'axe, les zones de prématurité : prématurité extrême de 22 à 27 SA plus 6 jours environ 10 pour cent, grande prématurité de 28 à 31 SA plus 6 jours environ 10 pour cent, prématurité moyenne ou tardive de 32 à 36 SA plus 6 jours environ 80 pour cent, puis à terme à partir de 37 SA. Le seuil de viabilité est à 22 SA ou 500 grammes ou 25 centimètres, et un terme inférieur à 28 SA est un facteur de gravité de la MAP.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"700\">Seuils gestationnels — MAP &amp; prématurité</text>\n          <text class=\"tx-muted\" x=\"310\" y=\"34\" text-anchor=\"middle\" font-size=\"10.5\">MAP : 22 → 36 SA + 6 j · prématurité = naissance &lt; 37 SA</text>\n\n          <rect class=\"fb-purple\" x=\"45\" y=\"44\" width=\"284\" height=\"22\" rx=\"5\"/>\n          <text class=\"tx-purple\" x=\"187\" y=\"59\" text-anchor=\"middle\" font-size=\"10\">Sulfate de Mg (neuroprotection) · Maternité type III — &lt; 32 SA</text>\n          <rect class=\"fb-teal\" x=\"45\" y=\"72\" width=\"341\" height=\"22\" rx=\"5\"/>\n          <text class=\"tx-teal\" x=\"215\" y=\"87\" text-anchor=\"middle\" font-size=\"10\"><span class=\"kw-ttt\">Corticothérapie</span> prénatale (béta-/<span class=\"kw-ttt\">dexaméthasone</span>) — &lt; 34 SA</text>\n          <rect class=\"fb-ok\" x=\"45\" y=\"100\" width=\"341\" height=\"22\" rx=\"5\"/>\n          <text class=\"tx-ok\" x=\"215\" y=\"115\" text-anchor=\"middle\" font-size=\"10\">Tocolyse <span class=\"kw-chiffre\">48 h</span> (transfert + délai cortico) — stop 34 SA</text>\n\n          <line class=\"ln-dash\" x1=\"329\" y1=\"44\" x2=\"329\" y2=\"150\" stroke-width=\"1.5\"/>\n          <line class=\"ln-dash\" x1=\"386\" y1=\"72\" x2=\"386\" y2=\"150\" stroke-width=\"1.5\"/>\n\n          <line class=\"ln\" x1=\"45\" y1=\"150\" x2=\"585\" y2=\"150\" stroke-width=\"2\"/>\n          <g stroke-width=\"2\">\n            <line class=\"ln\" x1=\"45\"  y1=\"145\" x2=\"45\"  y2=\"155\"/>\n            <line class=\"ln\" x1=\"215\" y1=\"145\" x2=\"215\" y2=\"155\"/>\n            <line class=\"ln\" x1=\"329\" y1=\"145\" x2=\"329\" y2=\"155\"/>\n            <line class=\"ln\" x1=\"386\" y1=\"145\" x2=\"386\" y2=\"155\"/>\n            <line class=\"ln\" x1=\"471\" y1=\"145\" x2=\"471\" y2=\"155\"/>\n            <line class=\"ln\" x1=\"585\" y1=\"145\" x2=\"585\" y2=\"155\"/>\n          </g>\n          <text class=\"tx-title\" x=\"45\"  y=\"169\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">22</text>\n          <text class=\"tx-title\" x=\"215\" y=\"169\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">28</text>\n          <text class=\"tx-title\" x=\"329\" y=\"169\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">32</text>\n          <text class=\"tx-title\" x=\"386\" y=\"169\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">34</text>\n          <text class=\"tx-title\" x=\"471\" y=\"169\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">37</text>\n          <text class=\"tx-title\" x=\"585\" y=\"169\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">41 SA</text>\n\n          <rect class=\"fb-red\"   x=\"45\"  y=\"184\" width=\"170\" height=\"42\" rx=\"5\"/>\n          <text class=\"tx-red\"   x=\"130\" y=\"201\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">Extrême</text>\n          <text class=\"tx-red\"   x=\"130\" y=\"216\" text-anchor=\"middle\" font-size=\"9.5\">22–27 SA+6 · ~<span class=\"kw-chiffre\">10 %</span></text>\n          <rect class=\"fb-amber\" x=\"215\" y=\"184\" width=\"114\" height=\"42\" rx=\"5\"/>\n          <text class=\"tx-amber\" x=\"272\" y=\"201\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">Grande</text>\n          <text class=\"tx-amber\" x=\"272\" y=\"216\" text-anchor=\"middle\" font-size=\"9.5\">28–31+6 · ~<span class=\"kw-chiffre\">10 %</span></text>\n          <rect class=\"fb-blue\"  x=\"329\" y=\"184\" width=\"142\" height=\"42\" rx=\"5\"/>\n          <text class=\"tx-blue\"  x=\"400\" y=\"201\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">Moyenne / tardive</text>\n          <text class=\"tx-blue\"  x=\"400\" y=\"216\" text-anchor=\"middle\" font-size=\"9.5\">32–36+6 · ~<span class=\"kw-chiffre\">80 %</span></text>\n          <rect class=\"fb-ok\"    x=\"471\" y=\"184\" width=\"114\" height=\"42\" rx=\"5\"/>\n          <text class=\"tx-ok\"    x=\"528\" y=\"201\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">À terme</text>\n          <text class=\"tx-ok\"    x=\"528\" y=\"216\" text-anchor=\"middle\" font-size=\"9.5\"><span class=\"kw-chiffre\">≥ 37</span> SA</text>\n\n          <text class=\"tx-muted\" x=\"45\" y=\"248\" text-anchor=\"start\" font-size=\"10\">◗ 22 SA = seuil de viabilité (ou <span class=\"kw-chiffre\">≥ 500 g</span> / <span class=\"kw-chiffre\">≥ 25 cm</span>)</text>\n          <text class=\"tx-muted\" x=\"45\" y=\"264\" text-anchor=\"start\" font-size=\"10\">◗ &lt; 28 SA = facteur de gravité de la MAP</text>\n        </svg>\n        <figcaption>Les seuils d’intervention se lisent par leur <strong>borne droite</strong> : sulfate de Mg &amp; maternité III avant 32 SA, <span class=\"kw-ttt\">corticothérapie</span> avant 34 SA, tocolyse jusqu’à 34 SA. Synthèse statique du chapitre MAP (obj-17/20/21).</figcaption>\n      </figure>\n\n      <h4>Définitions à connaître</h4>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Prématurité</strong></td><td>Naissance avant <span class=\"kw-chiffre\">37 SA</span></td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Menace</span> d’accouchement prématuré (MAP)</strong></td><td>Modifications cervicales + CU régulières et douloureuses, entre <span class=\"kw-chiffre\">22 SA</span> et <span class=\"kw-chiffre\">36 SA + 6 j</span></td></tr>\n          <tr><td><strong>Prématurité moyenne / tardive</strong></td><td><span class=\"kw-chiffre\">32-36 SA + 6 j</span> — ≈ <span class=\"kw-chiffre\">80 %</span> des AP</td></tr>\n          <tr><td><strong>Grande prématurité</strong></td><td><span class=\"kw-chiffre\">28-31 SA + 6 j</span> — ≈ <span class=\"kw-chiffre\">10 %</span> des AP</td></tr>\n          <tr><td><strong>Très grande prématurité / prématurité extrême</strong></td><td><span class=\"kw-chiffre\">22-27 SA + 6 j</span> — ≈ <span class=\"kw-chiffre\">10 %</span> des AP</td></tr>\n          <tr><td><strong>Seuil de viabilité</strong></td><td>Terme <span class=\"kw-chiffre\">≥ 22 SA</span> et/ou poids <span class=\"kw-chiffre\">≥ 500 g</span> et/ou taille <span class=\"kw-chiffre\">≥ 25 cm</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Diagnostic de MAP — 3 critères associés</h4>\n      <table >\n        <thead><tr><th>Critère</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Terme</strong></td><td>Entre <span class=\"kw-chiffre\">22 SA et 37 SA</span></td></tr>\n          <tr><td><strong>Contractions utérines</strong></td><td>\n            <strong>Régulières, douloureuses</strong> (à distinguer des CU physiologiques irrégulières et indolores)<br>\n            <strong>Cardiotocographie externe</strong> : objective et précise la nature des CU\n          </td></tr>\n          <tr><td><strong>Modifications cervicales</strong></td><td>\n            <strong>Au <span class=\"kw-alerte\">TV</span> :</strong> ramollissement, effacement, dilatation du col<br>\n            <strong><span class=\"kw-imagerie\">Échographie</span> du col :</strong> <span class=\"kw-chiffre\">longueur cervicale &lt; 25 mm</span> = col raccourci → MAP\n          </td></tr>\n        </tbody>\n      </table>\n\n      <h4>Marqueur <span class=\"kw-ttt\">biologique</span> d’aide au diagnostic</h4>\n      <div class=\"callout callout-info\">\n        <strong>Fibronectine fœtale</strong> (non systématique).\n        <ul>\n          <li><strong>Intérêt :</strong> prédit le risque d’accouchement avant <span class=\"kw-chiffre\">34 SA</span> (<span class=\"kw-chiffre\">VPN à 90 %</span>, spécificité supérieure au <span class=\"kw-alerte\">TV</span>)</li>\n          <li><strong>Rationnel :</strong> fibronectine normalement <strong>absente des sécrétions vaginales au-delà de <span class=\"kw-chiffre\">24 SA</span></strong></li>\n          <li>Sa positivité oriente vers un risque accru, sa négativité quasi-élimine la MAP</li>\n          <li><em>Réservée aux cas douteux ; ne se prescrit pas si MAP évidente</em></li>\n        </ul>\n      </div>\n\n      <h4>Col normal <span class=\"kw-bio\">vs</span> col raccourci</h4>\n      <ul>\n        <li><strong>Col normal de la nullipare :</strong> long, postérieur, fermé, consistance dure (« comme un nez »)</li>\n        <li>En cas de CU actives → le col se <strong>raccourcit, se centre, se ramollit, s’ouvre</strong></li>\n        <li><strong>Mesure échographique du col :</strong> coupe sagittale, visualisation orifices interne et externe, mesure de la longueur en dehors et pendant la contraction → <strong>seuil <span class=\"kw-chiffre\">25 mm</span></strong></li>\n      </ul>\n\n      <h4><span class=\"kw-def\">Diagnostic différentiel</span></h4>\n      <ul>\n        <li><strong>Contractions utérines physiologiques</strong> (Braxton-Hicks) : irrégulières, indolores, ne modifient pas le col</li>\n        <li><strong>Faux travail :</strong> CU douloureuses mais sans modification cervicale</li>\n        <li><strong>Travail réel</strong> avant <span class=\"kw-chiffre\">37 SA</span> : CU + col en travail (effacement et dilatation avancés) → <span class=\"kw-alerte\">urgence</span></li>\n        <li><strong><span class=\"kw-alerte\">Rupture</span> prématurée des membranes</strong> : peut être associée à MAP, ou isolée</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Attention.</strong> Ce n’est pas parce qu’une femme a des contractions utérines qu’elle a forcément une MAP. <strong>Au moindre doute → <span class=\"kw-imagerie\">échographie</span> du col</strong> pour mesurer objectivement la longueur cervicale.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 27 — Prévention des risques fœtaux · 359 — <span class=\"kw-alerte\">Détresse</span> respiratoire néonatale</em></p>","frequence":3},{"id":"24-19","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque de la menace d’accouchement prématuré","contenu":"<p>Le bilan étiologique d’une MAP est <strong>indispensable</strong> mais reste <strong>négatif dans <span class=\"kw-chiffre\">40 %</span></strong> des cas (MAP idiopathique). La connaissance des FR oriente la PEC et la prévention.</p>\n\n      <h4><span class=\"kw-def\">Facteurs de risque</span> maternels (terrain)</h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Âge</strong></td><td><span class=\"kw-clinique\">&lt; 18 ans</span> ou <span class=\"kw-clinique\">&gt; 35 ans</span></td></tr>\n          <tr><td><strong>Toxiques</strong></td><td><span class=\"kw-etio\">Tabac</span>, <span class=\"kw-etio\">alcool</span>, <span class=\"kw-clinique\">drogues</span> (cocaïne ++)</td></tr>\n          <tr><td><strong>Socio-éducatif</strong></td><td>Célibat, très bas niveau socio-économique, mauvais <span class=\"kw-def\">suivi</span> prénatal</td></tr>\n          <tr><td><strong>Travail / vie quotidienne</strong></td><td>Travail pénible, trajets longs quotidiens, nombreux enfants à charge</td></tr>\n          <tr><td><strong>Psychologique</strong></td><td><span class=\"kw-def\">Dépression</span>, anxiété, stress maternel</td></tr>\n          <tr><td><strong>Traumatisme</strong></td><td>Traumatisme abdominal</td></tr>\n          <tr><td><strong>Métrorragies</strong></td><td>Au 2ᵉ/3ᵉ trimestre, même hors <span class=\"kw-etio\">placenta praevia</span> (favorisent <span class=\"kw-etio\">RPM</span>)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Causes infectieuses</h4>\n      <ul>\n        <li><strong>Toute infection</strong> peut entraîner des CU via la <span class=\"kw-clinique\">fièvre</span></li>\n        <li><strong>Infections urinaires</strong>, bactériuries asymptomatiques (colonisation urinaire gravidique)</li>\n        <li><strong>Infections vaginales</strong> (<span class=\"kw-etio\">vaginose bactérienne</span>)</li>\n        <li><strong><span class=\"kw-etio\">Chorioamniotite</span></strong> (« infection de l’œuf ») et/ou <span class=\"kw-etio\">RPM</span></li>\n      </ul>\n\n      <h4>Facteurs cervicaux</h4>\n      <ul>\n        <li><strong>ATCD de conisation</strong> (<span class=\"kw-ttt\">chirurgie</span> visant à réséquer une partie du col)</li>\n        <li><strong>Col court</strong> mesuré en <span class=\"kw-imagerie\">échographie</span> (mesure non systématique)</li>\n        <li><strong>Béance cervico-isthmique</strong> (incompétence cervicale) — cause principale de <span class=\"kw-etio\">FCT</span> et AP très précoce / <span class=\"kw-etio\">RPM</span> avant <span class=\"kw-chiffre\">32 SA</span></li>\n      </ul>\n\n      <h4>Facteurs corps utérin</h4>\n      <ul>\n        <li><strong>Diminution de la taille utérine</strong> avant <span class=\"kw-ci\">grossesse</span> : fibromes, utérus polymyomateux, utérus diéthylstilbœstrol (exposition in utero à Distilbène®), malformations utérines (utérus hypoplasiques, unicornes, bicornes, cloisonnés)</li>\n        <li><strong>Augmentation de la distension utérine</strong> pendant la <span class=\"kw-ci\">grossesse</span> : hydramnios, macrosomie fœtale, <strong>grossesses multiples</strong> (taux de prématurité <span class=\"kw-chiffre\">45 %</span>, RR × 7)</li>\n      </ul>\n\n      <h4>Autres FR liés à la <span class=\"kw-ci\">grossesse</span></h4>\n      <ul>\n        <li><strong>FIV</strong></li>\n        <li><strong>Intervalle court</strong> entre <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> g</span>rossesses (&lt; <span class=\"kw-chiffre\">18 mois</span>)</li>\n        <li><strong><span class=\"kw-etio\">Placenta praevia</span></strong> (RR × 6-7 d’AP), décollement placentaire</li>\n        <li><strong>Anémie maternelle</strong></li>\n        <li><strong><span class=\"kw-def\">Diabète gestationnel</span></strong> (par macrosomie, hydramnios, infection intercurrente)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Facteurs de gravité de la MAP (rang C — à connaître).</strong>\n        <ul>\n          <li>Âge gestationnel <span class=\"kw-alerte\">&lt; 28 SA</span></li>\n          <li>Importance des modifications cervicales</li>\n          <li>Patiente accueillie dans une maternité de <strong>niveau non adapté</strong></li>\n          <li><strong><span class=\"kw-ci\">Grossesse</span> multiple</strong></li>\n          <li><strong><span class=\"kw-alerte\">Rupture</span> des membranes ou <span class=\"kw-etio\">chorioamniotite</span></strong> associée</li>\n          <li><strong>Métrorragies</strong> associées</li>\n          <li>Col fortement modifié, très menaçant, poche des eaux visible au spéculum</li>\n          <li>Tentative inefficace de tocolyse</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 255 — <span class=\"kw-def\">Diabète gestationnel</span> · 75 — Addiction <span class=\"kw-etio\">tabac</span> · 76 — Addictions <span class=\"kw-etio\">alcool</span> · 78 — Addictions drogues</em></p>","frequence":0},{"id":"24-20","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le bilan d’une menace d’accouchement prématuré","contenu":"<p>Le bilan d’une MAP comporte 4 volets : <strong>clinique</strong>, <strong>fœtal</strong>, <strong>étiologique</strong>, <strong>pré-thérapeutique</strong>.</p>\n\n      <h4>1. Bilan clinique</h4>\n      <ul>\n        <li><strong>Constantes habituelles</strong> : PA, FC, température, <span class=\"kw-bio\">BU</span></li>\n        <li><strong>Examen au spéculum</strong> : recherche d’un <strong>écoulement liquidien</strong> (<span class=\"kw-etio\">RPM</span> ?), métrorragies, leucorrhées</li>\n        <li><strong>Toucher vaginal</strong> : évaluation du col (ramollissement, effacement, dilatation)</li>\n        <li><strong>Mesure de la hauteur utérine :</strong>\n          <ul>\n            <li><strong>Augmentée</strong> → oriente vers une <strong>macrosomie fœtale</strong> ou un <strong>hydramnios</strong></li>\n            <li><strong>Diminuée</strong> → peut faire suspecter une <strong><span class=\"kw-alerte\">rupture</span> spontanée des membranes</strong></li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>2. Bilan fœtal</h4>\n      <ul>\n        <li><strong>Enregistrement du RCF</strong> par cardiotocographie externe</li>\n        <li><strong><span class=\"kw-imagerie\">Échographie</span> obstétricale :</strong> mouvements actifs fœtaux, estimation du poids fœtal, quantité de liquide amniotique, présentation, position du placenta</li>\n        <li><strong><span class=\"kw-imagerie\">Échographie</span> du col</strong> par voie endovaginale : mesure de la longueur cervicale, recherche d’une protrusion des membranes</li>\n      </ul>\n\n      <h4>3. Bilan étiologique</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">NFS, CRP</span></td><td>Recherche d’un <strong><span class=\"kw-def\">syndrome inflammatoire</span></strong> (<span class=\"kw-etio\">chorioamniotite</span>, infection)</td></tr>\n          <tr><td><span class=\"kw-bio\">ECBU</span></td><td>Recherche d’une <strong><span class=\"kw-def\">infection urinaire</span></strong> ou bactériurie</td></tr>\n          <tr><td><span class=\"kw-bio\">Prélèvement cervico-vaginal</span></td><td>Recherche de <strong><span class=\"kw-etio\">vaginose</span></strong>, <strong><span class=\"kw-etio\">streptocoque B</span></strong>, autres germes</td></tr>\n          <tr><td><strong>Test biochimique de <span class=\"kw-etio\">RPM</span></strong></td><td>Si doute sur <span class=\"kw-etio\">RPM</span> : <span class=\"kw-bio\">IGFBP-1 (Actim-PROM)</span>, <span class=\"kw-bio\">PAMG-1 (AmniSure)</span>, ou DAO — recherche de composants du liquide amniotique dans le vagin</td></tr>\n        </tbody>\n      </table>\n\n      <h4>4. <span class=\"kw-ci\">Bilan pré-thérapeutique</span></h4>\n      <ul>\n        <li><strong><span class=\"kw-bio\">Glycémie</span></strong> — risque de <strong>déséquilibre d’un <span class=\"kw-def\">diabète gestationnel</span> non diagnostiqué</strong> sous <span class=\"kw-ttt\">corticothérapie</span></li>\n        <li><strong><span class=\"kw-bio\">ECG</span></strong> avant <span class=\"kw-chiffre\">32 SA</span>, en prévision d’un traitement par <strong>sulfate de magnésium</strong> (jugé inutile selon Masson, à pondérer)</li>\n        <li><span class=\"kw-bio\">Groupe, Rhésus, RAI</span> en cas d’accouchement imminent</li>\n      </ul>\n\n      <h4>Fibronectine fœtale — quand la prescrire ?</h4>\n      <div class=\"callout callout-info\">\n        <strong>Indication.</strong> Cas <strong>douteux</strong> (CU ressenties par la patiente, col légèrement modifié) où le diagnostic de MAP n’est ni évident ni écarté.\n        <ul>\n          <li><strong>Si négative</strong> → quasi-élimine une MAP (VPN ≈ <span class=\"kw-chiffre\">90 %</span>) → <span class=\"kw-def\">surveillance</span> allégée</li>\n          <li><strong>Si positive</strong> → renforce le diagnostic → <span class=\"kw-alerte\">hospitalisation</span>, traitement</li>\n          <li><strong>Non indiquée si MAP évidente</strong> (col déjà très modifié) ❌</li>\n        </ul>\n      </div>\n\n      <h4>Conclusion du bilan</h4>\n      <ul>\n        <li>Confirmer / écarter le diagnostic de MAP</li>\n        <li>Identifier une étiologie traitable (infection, <span class=\"kw-etio\">RPM</span>)</li>\n        <li>Évaluer la sévérité (terme, modifications cervicales, RCF, <span class=\"kw-alerte\">signes de gravité</span> associés)</li>\n        <li>Orienter vers une <strong>maternité de niveau adapté</strong> (cf. obj-20)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 161 — Infection urinaire · 255 — <span class=\"kw-def\">Diabète gestationnel</span></em></p>","frequence":1},{"id":"24-21","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge d’une menace d’accouchement prématuré","contenu":"<p>La PEC d’une MAP repose sur <strong>3 piliers parallèles</strong> : <strong>tocolyse</strong> (gain de temps), <strong><span class=\"kw-ttt\">corticothérapie</span> prénatale</strong> (maturation pulmonaire fœtale), <strong>traitement étiologique</strong>. Le tout dans un <strong>lieu adapté au terme</strong>.</p>\n\n      <h4>Orientation — Niveau de maternité</h4>\n      <table >\n        <thead><tr><th>Niveau</th><th>SA</th><th>Poids</th><th>Plateau néonatal</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Type III</strong></td><td>&lt; <span class=\"kw-chiffre\">32 SA</span></td><td>&lt; <span class=\"kw-chiffre\">1500 g</span></td><td><span class=\"kw-alerte\">Réanimation</span> néonatale</td></tr>\n          <tr><td><strong>Type IIb</strong></td><td>&lt; <span class=\"kw-chiffre\">32 SA</span></td><td>&gt; <span class=\"kw-chiffre\">1500 g</span></td><td><span class=\"kw-alerte\">USI</span> néonatale</td></tr>\n          <tr><td><strong>Type IIa</strong></td><td><span class=\"kw-chiffre\">32-34 SA</span></td><td>&gt; <span class=\"kw-chiffre\">1500 g</span></td><td>Néonatalogie</td></tr>\n          <tr><td><strong>Type I</strong></td><td>&gt; <span class=\"kw-chiffre\">34 SA</span></td><td></td><td>Pas de néonatalogie</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Traitement étiologique</h4>\n      <ul>\n        <li><strong>Infection</strong> → <span class=\"kw-ttt\">antibiothérapie</span> adaptée à l’<span class=\"kw-bio\">antibiogramme</span></li>\n        <li><strong><span class=\"kw-alerte\">Rupture</span> des membranes</strong> → <span class=\"kw-ttt\">ATB en cure courte</span> (risque <span class=\"kw-etio\">infectieux</span> important)</li>\n      </ul>\n\n      <h4>Traitement symptomatique — Tocolyse</h4>\n      <div class=\"callout callout-info\">\n        <strong>Objectifs de la tocolyse ⭐.</strong>\n        <ul>\n          <li>Durée : <strong><span class=\"kw-chiffre\">48 h</span></strong> (aucun intérêt au-delà)</li>\n          <li>Permet d’<strong>organiser un transfert in utero</strong> vers une maternité adaptée</li>\n          <li>Permet à la <strong><span class=\"kw-ttt\">corticothérapie</span> d’atteindre son efficacité</strong></li>\n          <li>Une tocolyse prolongée n’a jamais fait preuve d’efficacité dans la prolongation de la <span class=\"kw-ci\">grossesse</span></li>\n          <li><strong>Pas de tocolyse après <span class=\"kw-chiffre\">34 SA</span></strong> ❌ (car pas de <span class=\"kw-ttt\">corticothérapie</span> au-delà)</li>\n        </ul>\n        <strong>Molécules.</strong>\n        <ul>\n          <li><strong>1ʳᵉ intention :</strong> <span class=\"kw-ttt\">inhibiteurs calciques — nifédipine</span> (Adalate®) — pas d’AMM mais largement utilisé (oral, peu coûteux)</li>\n          <li><strong>2ᵉ intention :</strong> <span class=\"kw-ttt\">antagonistes de l’ocytocine — atosiban</span> (Tractocile®) — AMM mais IV et coûteux ; préféré si MAP sévère</li>\n          <li><strong><span class=\"kw-ttt\">Salbutamol</span> :</strong> <span class=\"kw-ci\">plus recommandé</span> (effets indésirables fréquents et graves)</li>\n        </ul>\n        <strong>CI strictes à la tocolyse.</strong>\n        <ul>\n          <li><span class=\"kw-etio\">Chorioamniotite</span> (infection materno-fœtale)</li>\n          <li><span class=\"kw-ci\">Métrorragies importantes</span></li>\n          <li><span class=\"kw-ci\">Anomalies du RCF</span></li>\n        </ul>\n        <strong><span class=\"kw-ci\">CI relative</span> :</strong> <span class=\"kw-alerte\">rupture</span> des membranes (tocolyse possible si âge gestationnel précoce + CU).\n      </div>\n\n      <h4><span class=\"kw-ttt\">Corticothérapie</span> prénatale ⭐</h4>\n      <table >\n        <thead><tr><th>Volet</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Quand ?</strong></td><td>Avant <span class=\"kw-chiffre\">34 SA (+6 j selon KB)</span> devant toute suspicion de MAP</td></tr>\n          <tr><td><strong>Comment ?</strong></td><td><strong>1 seule cure</strong> par <strong>2 injections IM à <span class=\"kw-chiffre\">24 h</span> d’intervalle</strong></td></tr>\n          <tr><td><strong>Molécules</strong></td><td><span class=\"kw-ttt\">Bétaméthasone</span> (Célestène Chronodose®) ou <span class=\"kw-ttt\">dexaméthasone</span> — traversent le placenta</td></tr>\n          <tr><td><strong>Bénéfice</strong></td><td><strong><span class=\"kw-ttt\">Réduction</span> de <span class=\"kw-chiffre\">50 %</span> des complications néonatales</strong> ✅ : maladie des membranes hyalines, hémorragies intraventriculaires, entérocolites ulcéro-nécrosantes, décès</td></tr>\n          <tr><td><strong>Délai d’efficacité</strong></td><td>Efficace à <span class=\"kw-chiffre\">24 h</span></td></tr>\n          <tr><td><strong>Durée d’effet</strong></td><td>Bénéfice disparaît au-delà de <strong><span class=\"kw-chiffre\">7 jours</span></strong> ; <strong>cures répétées NON recommandées</strong> (effets délétères : perturbation axe HHS, insulinorésistance à l’âge adulte)</td></tr>\n          <tr><td><strong>CI</strong></td><td>Pas de <span class=\"kw-ci\">CI absolue</span> ; <strong><span class=\"kw-def\">diabète</span> et infection ne sont pas des CI</strong></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Sulfate de magnésium — neuroprotection fœtale</h4>\n      <ul>\n        <li><strong>Quand ?</strong> Avant <strong><span class=\"kw-chiffre\">32 SA</span></strong> en cas d’accouchement imminent, spontané ou programmé (dans les heures précédant la naissance)</li>\n        <li><strong>Posologie :</strong> dose de charge <strong><span class=\"kw-chiffre\">4 g</span> IV</strong>, puis entretien <strong><span class=\"kw-chiffre\">1 g/h</span> jusqu’à l’accouchement</strong></li>\n        <li><strong>Bénéfice :</strong> rôle de <strong>neuroprotection</strong> → <span class=\"kw-ttt\">réduction</span> du taux de <strong>paralysie cérébrale</strong> et des <strong>troubles du développement moteur</strong> chez le prématuré</li>\n        <li><strong><span class=\"kw-def\">Surveillance</span> :</strong> ROT, FR, diurèse</li>\n      </ul>\n\n      <h4>Mesures associées</h4>\n      <ul>\n        <li><strong>Repos</strong> sans alitement strict ❌ (majore risque de <span class=\"kw-def\">MTEV</span>)</li>\n        <li><strong>Bas de contention</strong> — prévention <span class=\"kw-def\">MTEV</span></li>\n        <li><strong>Antipyrétique</strong> (<span class=\"kw-ttt\">paracétamol</span>), <strong>antispasmodique</strong> (<span class=\"kw-ttt\">phloroglucinol</span>)</li>\n        <li><strong>Ig anti-D</strong> systématique si métrorragies chez patiente Rh- (et fœtus Rh+ ou inconnu)</li>\n        <li><strong>Rencontre avec l’équipe de pédiatrie</strong>, préparation à la prématurité éventuelle, <strong>soutien psychologique</strong></li>\n      </ul>\n\n      <h4><span class=\"kw-def\">Surveillance</span></h4>\n      <ul>\n        <li><strong>Clinique :</strong> interrogatoire ou tocométrie externe (recherche <span class=\"kw-ttt\">réduction</span> des CU)</li>\n        <li><strong>Échographique :</strong> pas de nouvelle <span class=\"kw-imagerie\">échographie</span> du col en l’absence de nouvel élément intercurrent</li>\n        <li><strong><span class=\"kw-alerte\">Hospitalisation</span> prolongée non recommandée</strong> ❌ — ne réduit pas le risque d’AP</li>\n        <li>Après la sortie : <span class=\"kw-def\">suivi</span> par sage-femme libérale à domicile possible</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 359 — <span class=\"kw-alerte\">Détresse</span> respiratoire néonatale · 27 — Prévention des risques fœtaux · 326 — Anti-thrombotiques · 23 — <span class=\"kw-ci\">Grossesse</span> normale</em></p>","frequence":2},{"id":"24-22","rang":"A","rubrique":"Prise en charge","titre":"Connaître les mesures de prévention de la menace d’accouchement prématuré","contenu":"<p>La prévention de la MAP repose sur (1) <strong>prévention pré-conceptionnelle</strong>, (2) <strong>prise en charge des FR</strong> pendant la <span class=\"kw-ci\">grossesse</span>, (3) <strong>traitements spécifiques</strong> chez les patientes à haut risque.</p>\n\n      <h4>Prévention pré-conceptionnelle</h4>\n      <ul>\n        <li><strong><span class=\"kw-ttt\">Sevrage</span> tabagique</strong> — seul FR modifiable d’AP dont le sevrage est associé à une diminution de la prématurité</li>\n        <li><strong>Limitation des grossesses multiples</strong> en cas de PMA (transfert d’1 seul embryon)</li>\n        <li><strong>Information</strong> sur les risques des grossesses rapprochées (intervalle &lt; <span class=\"kw-chiffre\">18 mois</span>)</li>\n        <li><strong>Bilan préconceptionnel</strong> en cas d’ATCD d’AP ou de <span class=\"kw-etio\">FCT</span></li>\n      </ul>\n\n      <h4>Prise en charge des FR pendant la <span class=\"kw-ci\">grossesse</span></h4>\n      <table >\n        <thead><tr><th>FR</th><th>Mesure</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Tabac</span></strong></td><td><strong><span class=\"kw-ttt\">Sevrage</span></strong> (seul FR modifiable avec efficacité prouvée)</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Alcool</span>, toxiques</strong></td><td>Arrêt + accompagnement addictologique</td></tr>\n          <tr><td><strong>Travail pénible</strong></td><td>Arrêt de travail (station debout &gt; <span class=\"kw-chiffre\">6 h</span>, longs trajets)</td></tr>\n          <tr><td><strong>Stress maternel</strong></td><td>PEC psychologique possible, soutien</td></tr>\n          <tr><td><strong>Alimentation</strong></td><td>Équilibrée</td></tr>\n          <tr><td><strong>Pathologies préexistantes</strong></td><td>Optimisation (<span class=\"kw-def\">diabète</span>, <span class=\"kw-def\">asthme</span>, <span class=\"kw-def\">HTA</span>...)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Malformations utérines</h4>\n      <ul>\n        <li><strong>Rechercher</strong> les malformations utérines (<span class=\"kw-imagerie\">échographie</span> pelvienne 3D, <span class=\"kw-imagerie\">hystérographie</span>)</li>\n        <li><strong>Corriger</strong> avant la <span class=\"kw-ci\">grossesse</span> si possible : <span class=\"kw-ttt\">résection de cloison utérine</span></li>\n      </ul>\n\n      <h4>Vaginose <span class=\"kw-etio\">bactérienne</span></h4>\n      <div class=\"callout callout-info\">\n        <strong>Si ATCD d’AP dans un contexte d’infection materno-fœtale <span class=\"kw-etio\">bactérienne</span> :</strong>\n        <ol>\n          <li><strong><span class=\"kw-def\">Dépistage</span></strong> de la <span class=\"kw-etio\">vaginose bactérienne</span> par <strong>prélèvement vaginal au 1ᵉʳ trimestre</strong></li>\n          <li><strong>Si positive → traitement systématique :</strong> <span class=\"kw-ttt\">métronidazole</span> ou <span class=\"kw-ttt\">clindamycine</span> pendant <span class=\"kw-chiffre\">7 jours</span></li>\n        </ol>\n      </div>\n\n      <h4>Béance cervicale — Cerclage <span class=\"kw-bio\">vs</span> progestérone</h4>\n      <table >\n        <thead><tr><th>Contexte</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-chiffre\">≥ 3</span> ATCD d’AP ou <span class=\"kw-etio\">FCT</span></strong></td><td><strong>Cerclage formellement indiqué</strong> (placé à la fin du 1ᵉʳ trimestre)</td></tr>\n          <tr><td><strong>1 ou 2 ATCD d’AP ou <span class=\"kw-etio\">FCT</span></strong></td><td><span class=\"kw-def\">Surveillance</span> écho col entre 16 et <span class=\"kw-chiffre\">22 SA</span> + <strong>cerclage si col &lt; <span class=\"kw-chiffre\">25 mm</span></strong> ; progestérone micronisée vaginale possible</td></tr>\n          <tr><td><strong>Pas d’ATCD</strong></td><td><span class=\"kw-imagerie\">Échographie</span> entre 16 et <span class=\"kw-chiffre\">24 SA</span> ; si <strong>col &lt; <span class=\"kw-chiffre\">20 mm</span> → progestérone micronisée vaginale</strong> formellement indiquée</td></tr>\n          <tr><td><strong>Cerclage préventif systématique</strong></td><td><span class=\"kw-ci\">Non recommandé</span> sur seul ATCD de conisation, malformation utérine, <span class=\"kw-ci\">grossesse</span> gémellaire ou ATCD isolé d’AP</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Principe du cerclage</h4>\n      <ul>\n        <li><strong>Définition :</strong> mise en place d’un « nœud » (suture) autour du col pour empêcher mécaniquement son ouverture</li>\n        <li><strong>Placement :</strong> fin du 1ᵉʳ trimestre</li>\n        <li><strong>Retrait :</strong> en fin de <span class=\"kw-ci\">grossesse</span> pour permettre l’accouchement</li>\n        <li><strong>Attention :</strong> le cerclage n’est <strong>pas un traitement de la MAP</strong> mais une mesure préventive chez patientes à risque</li>\n      </ul>\n\n      <h4>Mesures NON recommandées</h4>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">Hospitalisation</span> prolongée</strong> ❌ — ne réduit pas le risque d’AP, majore le risque <span class=\"kw-def\">MTEV</span></li>\n        <li><strong>Repos au lit strict</strong> ❌ — pas d’efficacité, majore <span class=\"kw-def\">MTEV</span></li>\n        <li><strong>Recherche systématique de fibronectine fœtale</strong> ❌ — réservée aux cas de suspicion de MAP</li>\n        <li><strong>Mesure systématique du col</strong> en <span class=\"kw-imagerie\">échographie</span> chez patientes sans FR ❌</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Risque de récidive</strong> lors de la <span class=\"kw-ci\">grossesse</span> suivante est <strong>important</strong>, justifiant un bilan étiologique attentif, bien souvent négatif (<span class=\"kw-chiffre\">40 %</span> idiopathiques).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 75 — Addiction <span class=\"kw-etio\">tabac</span> · 161 — Infection urinaire · 36 — Contraception</em></p>","frequence":0},{"id":"24-23","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes d’orientation diagnostique et de gravité en cas de fièvre au cours de la grossesse","contenu":"<p>La <span class=\"kw-clinique\">fièvre</span> pendant la <span class=\"kw-ci\">grossesse</span> est une situation <strong>fréquente</strong> (<span class=\"kw-chiffre\">10-15 %</span> des grossesses). <strong>Définition :</strong> température maternelle <span class=\"kw-chiffre\">&gt; 38 °C</span>.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Dogme.</strong> Toute <span class=\"kw-clinique\">fièvre</span> in utero est une infection <strong>jusqu’à preuve du contraire</strong> — et plus précisément une <span class=\"kw-alerte\">listériose jusqu’à preuve du contraire</span>.\n      </div>\n\n      <h4>Étiologies à connaître par fréquence</h4>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Infections bénignes</strong> (<span class=\"kw-etio\">grippe</span>, gastro-entérite, angine)</td><td>Le plus souvent — PEC à domicile possible</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Pyélonéphrite</span> aiguë gravidique</strong> ⭐</td><td><strong>Étiologie la plus fréquente</strong> — <span class=\"kw-clinique\">fièvre</span> + douleur lombaire + brûlures mictionnelles</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Listériose</span></strong></td><td>Grave — passage transplacentaire, risque de mort fœtale, prématurité, séquelles néonatales</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Chorioamniotite</span></strong></td><td>Grave — <span class=\"kw-clinique\">fièvre</span> + CU + <span class=\"kw-clinique\">tachycardie</span> fœtale + leucorrhées suspectes</td></tr>\n          <tr><td><strong>Infections materno-fœtales</strong></td><td><span class=\"kw-etio\">Rubéole</span>, <span class=\"kw-etio\">toxoplasmose</span>, <span class=\"kw-etio\">herpès</span>, <span class=\"kw-etio\">syphilis</span>, <span class=\"kw-etio\">CMV</span>, <span class=\"kw-etio\">VIH</span>, hépatites virales (donnent rarement de la <span class=\"kw-clinique\">fièvre</span>)</td></tr>\n          <tr><td><strong>Causes digestives</strong></td><td><span class=\"kw-etio\">Appendicite</span>, <span class=\"kw-etio\">cholécystite</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Signes d’orientation par contexte</h4>\n      <ul>\n        <li><strong>Signes urinaires</strong> (douleurs lombaires, brûlures mictionnelles, <span class=\"kw-bio\">BU</span> positive) → <strong><span class=\"kw-etio\">PNA</span> gravidique</strong> ++</li>\n        <li><strong>Signes obstétricaux</strong> (CU + écoulement liquide amniotique + leucorrhées suspectes) → <strong><span class=\"kw-etio\">chorioamniotite</span> / <span class=\"kw-etio\">RPM</span></strong></li>\n        <li><strong>Syndrome grippal</strong> en période d’épidémie → infection bénigne probable</li>\n        <li><strong>Signes digestifs</strong> (douleur fosse iliaque droite, défense, signe de Murphy) → <span class=\"kw-etio\">appendicite</span> / <span class=\"kw-etio\">cholécystite</span></li>\n        <li><strong><span class=\"kw-clinique\">Fièvre</span> isolée, mal expliquée</strong>, hors contexte épidémique → <strong>évoquer <span class=\"kw-etio\">listériose</span></strong> ++</li>\n        <li><strong>Diminution des mouvements actifs fœtaux + <span class=\"kw-clinique\">tachycardie</span> fœtale</strong> → souffrance fœtale → <strong><span class=\"kw-etio\">listériose</span> ? <span class=\"kw-etio\">chorioamniotite</span> ?</strong></li>\n      </ul>\n\n      <h4><span class=\"kw-alerte\">Signes de gravité</span> — Indications d’<span class=\"kw-alerte\">hospitalisation</span></h4>\n      <div class=\"callout callout-danger\">\n        <strong>Indications d’<span class=\"kw-alerte\">hospitalisation</span> systématique :</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Signes évocateurs de PNA</span></li>\n          <li><span class=\"kw-alerte\">Signes évocateurs de chorioamniotite</span></li>\n          <li><strong><span class=\"kw-clinique\">Fièvre</span> en apparence bénigne mais mal expliquée</strong> (isolée, syndrome grippal hors contexte épidémique...)</li>\n          <li><strong><span class=\"kw-clinique\">Fièvre</span> + signes d’hypoxie fœtale</strong> (diminution mouvements, <span class=\"kw-clinique\">tachycardie</span> fœtale) → <span class=\"kw-etio\">listériose</span> ? <span class=\"kw-etio\">chorioamniotite</span> ?</li>\n          <li><strong><span class=\"kw-etio\">Appendicite</span>, <span class=\"kw-etio\">cholécystite</span></strong> ou autre cause chirurgicale</li>\n          <li><strong><span class=\"kw-clinique\">Hyperthermie</span> &gt; <span class=\"kw-chiffre\">38,5 °C</span></strong> sans cause identifiée</li>\n          <li><strong>Mauvaise tolérance maternelle</strong> (<span class=\"kw-clinique\">frissons</span>, <span class=\"kw-clinique\">AEG</span>, signes de <span class=\"kw-def\">sepsis</span>)</li>\n        </ul>\n      </div>\n\n      <h4>Retentissement obstétrical à évaluer systématiquement</h4>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">Menace</span> d’accouchement prématuré</strong> (la <span class=\"kw-clinique\">fièvre</span> peut provoquer des CU = FR de MAP)</li>\n        <li><strong>Hypoxie fœtale</strong> (<span class=\"kw-clinique\">tachycardie</span> fœtale, diminution des mouvements actifs)</li>\n        <li><strong><span class=\"kw-alerte\">Rupture</span> prématurée des membranes</strong></li>\n      </ul>\n\n      <h4>Situations autorisant une PEC à domicile</h4>\n      <ul>\n        <li><strong>Étiologie bénigne clairement identifiée</strong> : syndrome grippal typique en période d’épidémie, gastro-entérite bénigne...</li>\n        <li><strong>Absence de CU</strong></li>\n        <li><strong>Mouvements fœtaux et RCF normaux</strong></li>\n        <li><strong>Tolérance maternelle correcte</strong></li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — Infection urinaire · 157 — Septicémie/Bactériémie · 147 — <span class=\"kw-clinique\">Fièvre</span> aiguë chez l’adulte · 162 — IST · 27 — Prévention des risques fœtaux (toxoplasmose)</em></p>","frequence":1},{"id":"24-24","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le bilan en cas de fièvre au cours de la grossesse","contenu":"<p>Le bilan d’une <span class=\"kw-clinique\">fièvre</span> pendant la <span class=\"kw-ci\">grossesse</span> vise à <strong>identifier rapidement</strong> la cause (notamment <strong><span class=\"kw-etio\">listériose</span></strong> ++) et à <strong>évaluer le retentissement obstétrical</strong>.</p>\n\n      <h4>Interrogatoire</h4>\n      <ul>\n        <li><strong>ATCD prédisposants :</strong> infections urinaires à répétition, uropathies, maladies chroniques, immunodépression, prématurité, <span class=\"kw-etio\">tabac</span>...</li>\n        <li><strong>Traitements en cours</strong></li>\n        <li><strong>Contexte :</strong> épidémie, voyage, alimentation à risque (fromage au lait cru → <span class=\"kw-etio\">listeria</span>)</li>\n        <li><strong>Signes d’accompagnement :</strong>\n          <ul>\n            <li><strong>Généraux :</strong> <span class=\"kw-clinique\">frissons</span>, ORL, pulmonaires, digestifs, syndrome grippal</li>\n            <li><strong>Urinaires :</strong> douleurs lombaires, brûlures mictionnelles</li>\n            <li><strong>Obstétricaux :</strong> CU, écoulement de liquide amniotique, leucorrhées, saignements</li>\n          </ul>\n        </li>\n        <li><strong>Mouvements actifs fœtaux</strong></li>\n        <li><strong>Résultats des <span class=\"kw-bio\">sérologies</span></strong> (<span class=\"kw-etio\">toxoplasmose</span>, <span class=\"kw-etio\">rubéole</span> — donnent rarement de la <span class=\"kw-clinique\">fièvre</span>)</li>\n      </ul>\n\n      <h4>Examen clinique</h4>\n      <ul>\n        <li><strong>Constantes :</strong> température, pouls, PA</li>\n        <li><strong>Examen général :</strong> ORL, cardiorespiratoire, aires lymphonodales, état cutané, <span class=\"kw-def\">syndrome méningé</span>, abdomen, fosses lombaires</li>\n        <li><strong>Examen urinaire :</strong> aspect des urines, <span class=\"kw-bio\">bandelette urinaire</span></li>\n        <li><strong>Examen obstétrical :</strong>\n          <ul>\n            <li><strong>Hauteur utérine</strong></li>\n            <li><strong>Bruits du cœur / RCF</strong></li>\n            <li><strong>Vulve :</strong> vésicules ou ulcérations herpétiques</li>\n            <li><strong>Au spéculum :</strong> <span class=\"kw-alerte\">rupture</span> des membranes, leucorrhées, vésicules herpétiques</li>\n            <li><strong><span class=\"kw-alerte\">TV</span> :</strong> modifications cervicales</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>Bilan paraclinique systématique</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Justification</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">ECBU</span></td><td>Recherche d’une <strong><span class=\"kw-def\">infection urinaire</span> / <span class=\"kw-etio\">PNA</span></strong></td></tr>\n          <tr><td><span class=\"kw-bio\">NFS, CRP</span></td><td><span class=\"kw-def\">Syndrome inflammatoire</span>. <strong>Attention :</strong> hyperleucocytose physiologique pendant la <span class=\"kw-ci\">grossesse</span></td></tr>\n          <tr><td><span class=\"kw-bio\">VS</span></td><td><strong>N’a aucune valeur</strong> pendant la <span class=\"kw-ci\">grossesse</span> — <strong>physiologiquement augmentée</strong></td></tr>\n          <tr><td><span class=\"kw-bio\">Hémocultures</span></td><td>Si T° <strong>&gt; <span class=\"kw-chiffre\">38,5 °C</span></strong> — <strong>2 paires</strong>, recherche de <strong><span class=\"kw-etio\">Listeria</span></strong> ++</td></tr>\n          <tr><td><strong>Électro-cardiotocographie</strong></td><td>Enregistrement du RCF + CU si âge gestationnel le permet (<strong>&gt; <span class=\"kw-chiffre\">25 SA</span></strong>)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Bilan en milieu hospitalier — Examens complémentaires</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">ECBU + Prélèvement vaginal + Hémocultures avec recherche de Listeria</span></td><td>Bilan microbiologique complet (la <strong><span class=\"kw-bio\">sérologie</span> <span class=\"kw-etio\">listeria</span> est sans valeur</strong>)</td></tr>\n          <tr><td><span class=\"kw-bio\">NFS / CRP</span></td><td>Recherche d’hyperleucocytose (GB &gt; <span class=\"kw-chiffre\">15 G/L</span>) ; pondérer avec l’hyperleucocytose physiologique</td></tr>\n          <tr><td><span class=\"kw-bio\">Sérologies selon contexte</span></td><td><span class=\"kw-etio\">Rubéole</span>, <span class=\"kw-etio\">toxoplasmose</span>, <span class=\"kw-def\">hépatite</span>, <span class=\"kw-etio\">CMV</span>, <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">parvovirus B19</span></td></tr>\n          <tr><td><strong>RCF + CU</strong></td><td>Si âge gestationnel &gt; <span class=\"kw-chiffre\">25 SA</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Échographie obstétricale</span></td><td>Apprécier le bien-être fœtal + quantité de liquide amniotique</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Examens orientés selon contexte clinique</h4>\n      <ul>\n        <li><strong>Suspicion de <span class=\"kw-etio\">chorioamniotite</span></strong> : <span class=\"kw-bio\">NFS, CRP, prélèvement vaginal, bactériologie du liquide amniotique, écouvillon</span></li>\n        <li><strong>Suspicion de <span class=\"kw-etio\">RPM</span></strong> : <span class=\"kw-bio\">IGFBP-1, PAMG-1, DAO, Amniocheck, PromTest®</span></li>\n        <li><strong>Suspicion d’<span class=\"kw-etio\">appendicite</span></strong> : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-imagerie\">échographie abdominale</span> (± <span class=\"kw-imagerie\">IRM</span> en cas de doute, <span class=\"kw-imagerie\">TDM</span> dosimétrie limitée)</li>\n        <li><strong>Suspicion d’<span class=\"kw-def\">hépatite</span></strong> : <span class=\"kw-bio\">ASAT</span>/<span class=\"kw-bio\">ALAT</span>, <span class=\"kw-bio\">PAL</span>, <span class=\"kw-bio\">bilirubine</span>, <span class=\"kw-bio\">sérologies</span> hépatiques (Ag HBs, Ac anti-HBs, Ac anti-HBc, VHA, <span class=\"kw-etio\">VHC</span>), test de la MNI</li>\n        <li><strong>Si <span class=\"kw-clinique\">fièvre</span> à l’accouchement</strong> : prélèvements périphériques + aspiration du liquide gastrique chez le nouveau-né + <strong>mise en culture du placenta</strong></li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — Infection urinaire · 27 — Prévention des risques fœtaux (toxoplasmose) · 173 — Zoonose · 147 — <span class=\"kw-clinique\">Fièvre</span> aiguë adulte · 168 — Herpesvirus</em></p>","frequence":0},{"id":"24-25","rang":"A","rubrique":"Prise en charge","titre":"Connaître la prise en charge d’une fièvre au cours de la grossesse","contenu":"<p>La PEC d’une <span class=\"kw-clinique\">fièvre</span> pendant la <span class=\"kw-ci\">grossesse</span> repose sur (1) <strong><span class=\"kw-ttt\">antibiothérapie</span> probabiliste anti-<span class=\"kw-etio\">Listeria</span> immédiate</strong> en cas d’<span class=\"kw-alerte\">hospitalisation</span>, (2) <strong>traitement symptomatique</strong> (<span class=\"kw-ttt\">paracétamol</span>), (3) <strong><span class=\"kw-def\">surveillance</span> maternelle et fœtale rapprochée</strong>, (4) <strong>traitement étiologique adapté</strong> aux résultats.</p>\n\n      <h4>PEC à domicile — situations autorisées</h4>\n      <div class=\"callout callout-info\">\n        <strong>Domicile autorisé seulement si :</strong>\n        <ul>\n          <li><strong>Étiologie bénigne clairement identifiée</strong> (syndrome grippal en épidémie, gastro-entérite)</li>\n          <li><strong>Absence de CU</strong></li>\n          <li><strong>Mouvements fœtaux normaux</strong></li>\n          <li><strong>RCF normal</strong> (si âge gestationnel adapté)</li>\n        </ul>\n        <strong>Mesures :</strong> <span class=\"kw-ttt\">paracétamol</span>, traitement symptomatique adapté, bonne hydratation, <span class=\"kw-def\">surveillance</span> rapprochée + consigne de reconsulter en <span class=\"kw-alerte\">urgence</span> si aggravation, CU, baisse des mouvements fœtaux, persistance &gt; <span class=\"kw-chiffre\">48 h</span>.\n      </div>\n\n      <h4>PEC hospitalière — Sans attendre les résultats</h4>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste anti-<span class=\"kw-etio\">Listeria</span> immédiate</strong> en cas d’<span class=\"kw-alerte\">hospitalisation</span>, <strong>en dehors d’une orientation étiologique claire</strong> :\n        <ul>\n          <li><strong>1ʳᵉ intention :</strong> <span class=\"kw-ttt\">Amoxicilline 3 g/jour</span> per os ou IV pendant <strong><span class=\"kw-chiffre\">10 jours</span></strong></li>\n          <li><strong>Si <span class=\"kw-ci\">allergie</span> :</strong> <span class=\"kw-ttt\">érythromycine</span></li>\n          <li><strong>Si signes de <span class=\"kw-etio\">chorioamniotite</span></strong> : <span class=\"kw-ttt\">C3G (céfotaxime / ceftriaxone) + Aminoside (gentamicine)</span> en IV — <em><span class=\"kw-ttt\">amoxicilline</span> selon KB</em></li>\n        </ul>\n        <strong>+ Antipyrétique :</strong> <span class=\"kw-ttt\">paracétamol</span> <span class=\"kw-chiffre\">1 g</span> ×<span class=\"kw-chiffre\"> 4/jour</span>. <strong>Pas d’<span class=\"kw-ttt\">AINS</span> pendant la <span class=\"kw-ci\">grossesse</span></strong> ❌.<br>\n        <strong>+ Bonne hydratation</strong>.\n      </div>\n\n      <h4><span class=\"kw-def\">Surveillance</span> étroite</h4>\n      <ul>\n        <li><strong>Maternelle :</strong> température, FC, PA, FR, état général, diurèse</li>\n        <li><strong>Obstétricale :</strong> CU (tocométrie), col utérin (<span class=\"kw-alerte\">TV</span> répété ± écho), pertes vaginales</li>\n        <li><strong>Fœtale :</strong> RCF en continu ou enregistrements répétés, mouvements actifs perçus par la mère</li>\n        <li><strong><span class=\"kw-ttt\">Biologique</span> :</strong> <span class=\"kw-bio\">NFS</span> + <span class=\"kw-bio\">CRP</span> de contrôle à <span class=\"kw-chiffre\">48 h</span> ± <span class=\"kw-bio\">hémocultures</span> de contrôle</li>\n      </ul>\n\n      <h4>PEC étiologique selon résultats</h4>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Listériose</span> confirmée</strong></td><td><span class=\"kw-ttt\">Amoxicilline IV 6 g/jour</span> pendant <strong><span class=\"kw-chiffre\">3 semaines</span></strong> ± <span class=\"kw-ttt\">gentamicine</span>. <strong>Déclaration obligatoire</strong>.</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Pyélonéphrite</span> aiguë gravidique</strong></td><td><span class=\"kw-ttt\">C3G (céfotaxime / ceftriaxone)</span> IV puis relais oral (amox-clav, FQ <span class=\"kw-ci\">contre-indiquées</span> sauf <span class=\"kw-etio\">E. coli</span> résistant) — durée totale <span class=\"kw-chiffre\">10-14 jours</span>. <strong><span class=\"kw-alerte\">Hospitalisation</span> systématique</strong>.</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Chorioamniotite</span></strong></td><td><span class=\"kw-ttt\">C3G + Aminoside</span> IV + <strong>extraction fœtale en <span class=\"kw-alerte\">urgence</span> par césarienne</strong> ++ ; <span class=\"kw-ci\">tocolyse CI</span> dans ce contexte ⚠️</td></tr>\n          <tr><td><strong>Infections virales</strong> (<span class=\"kw-etio\">grippe</span>, gastro-entérite)</td><td>Traitement symptomatique. <strong><span class=\"kw-ttt\">Oseltamivir</span></strong> possible si <span class=\"kw-etio\">grippe</span> avérée et formes graves.</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Toxoplasmose</span> maternelle</strong> (séroconversion)</td><td><span class=\"kw-ttt\">Spiramycine</span> jusqu’à <span class=\"kw-chiffre\">18 SA</span> puis <span class=\"kw-ttt\">pyriméthamine</span>-<span class=\"kw-ttt\">sulfadiazine</span> selon contamination fœtale</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Appendicite</span> / <span class=\"kw-etio\">cholécystite</span></strong></td><td>Traitement chirurgical en <span class=\"kw-alerte\">urgence</span> ± ATB</td></tr>\n        </tbody>\n      </table>\n\n      <h4>PEC néonatale en cas de <span class=\"kw-clinique\">fièvre</span> à l’accouchement</h4>\n      <ul>\n        <li><strong>Prélèvements périphériques</strong> chez le nouveau-né</li>\n        <li><strong>Aspiration du liquide gastrique</strong></li>\n        <li><strong>Mise en culture du placenta</strong></li>\n        <li><strong>ATB néonatale probabiliste</strong> selon contexte (anti-<span class=\"kw-etio\">Listeria</span> + anti-Strepto B)</li>\n        <li><strong><span class=\"kw-def\">Surveillance</span> pédiatrique rapprochée</strong> (<span class=\"kw-def\">sepsis</span> néonatal)</li>\n      </ul>\n\n      <h4>Cas particuliers — Conseils alimentaires anti-<span class=\"kw-etio\">Listeria</span></h4>\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-def\">Prévention primaire</span> de la <span class=\"kw-etio\">listériose</span> pendant la <span class=\"kw-ci\">grossesse</span> :</strong>\n        <ul>\n          <li>Éviter <strong>fromages au lait cru</strong>, à pâte molle, croûtes</li>\n          <li>Éviter <strong>charcuteries</strong> artisanales, rillettes, pâtés, foie gras non stérilisé</li>\n          <li>Éviter <strong>poissons fumés, crustacés crus, sushis</strong></li>\n          <li>Bien <strong>cuire les viandes</strong> et lavages soigneux des fruits/légumes</li>\n          <li>Respecter la chaîne du froid, dates de péremption</li>\n        </ul>\n      </div>\n\n      <h4>Synthèse — Algorithme</h4>\n      <ol>\n        <li><strong><span class=\"kw-clinique\">Fièvre</span> &gt; <span class=\"kw-chiffre\">38 °C</span> confirmée</strong> → interrogatoire + examen complet</li>\n        <li><strong>Étiologie bénigne identifiée + bonne tolérance</strong> → PEC à domicile, <span class=\"kw-ttt\">paracétamol</span>, <span class=\"kw-def\">surveillance</span></li>\n        <li><strong>Sinon ou doute</strong> → <span class=\"kw-alerte\">hospitalisation</span></li>\n        <li><strong>Bilan paraclinique</strong> (cf. obj-23) + <strong><span class=\"kw-ttt\">amoxicilline</span> <span class=\"kw-chiffre\">3 g/j</span></strong> sans attendre</li>\n        <li><strong><span class=\"kw-def\">Surveillance</span> maternelle + fœtale</strong> rapprochée</li>\n        <li><strong>Adaptation</strong> selon résultats microbiologiques</li>\n      </ol>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — Infection urinaire · 27 — Prévention des risques fœtaux (toxoplasmose) · 173 — Zoonose (listériose) · 147 — <span class=\"kw-clinique\">Fièvre</span> aiguë adulte · 166 — <span class=\"kw-etio\">Grippe</span></em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://archives.uness.fr/sites/campus-unf3s-2014/maieutique/UE-obstetrique/rcf/site/html/cours.pdf","label":"UNESS / UNF3S — Cours RCF (maïeutique, PDF)"},{"href":"https://www.aly-abbara.com/livre_gyn_obs/termes/bien_etre_foetal/rythme_cardiaque_foetal_RCF.html","label":"Aly-Abbara — Rythme cardiaque fœtal (exemples)"}],"cards":[]};